// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC721/IERC721.sol";
import "../Interfaces.sol";

interface IDSCRPoolVault {
    function deposit(uint256 assets, address receiver) external returns (uint256 shares);
    function withdraw(uint256 assets, address receiver, address owner) external returns (uint256 shares);
    function redeem(uint256 shares, address receiver, address owner) external returns (uint256 assets);
    function lockForLoan(uint256 amount) external;
    function unlockFromLoan(uint256 amount) external;
    function reportYield(uint256 amount) external;
    function disburse(address recipient, uint256 amount) external;
    function totalAssets() external view returns (uint256);
    function availableLiquidity() external view returns (uint256);
    function lockedLiquidity() external view returns (uint256);
    function convertToShares(uint256 assets) external view returns (uint256);
    function convertToAssets(uint256 shares) external view returns (uint256);
}

interface IDSCRRiskConfig {
    struct DSCRProductRisk {
        uint256 productId;
        uint256 maxLtvBps;
        uint256 minDscrBps;
        uint256 interestRateBps;
        uint256 originationFeeBps;
        uint256 termMonths;
        uint256 minLoanSize;
        uint256 maxLoanSize;
        uint256 maxBorrowerExposure;
        uint256 insuranceReserveBps;
        uint256 protocolFeeBps;
        bool active;
    }

    function getDSCRProductRisk(uint256 productId) external view returns (DSCRProductRisk memory);
    function setDSCRProductRisk(uint256 productId, DSCRProductRisk calldata config) external;
    function isDSCRProductActive(uint256 productId) external view returns (bool);

    event DSCRProductRiskUpdated(
        uint256 indexed productId,
        uint256 maxLtvBps,
        uint256 minDscrBps,
        uint256 interestRateBps,
        uint256 termMonths
    );
}

interface IDSCRLoanReceipt is IERC721 {
    enum DSCRLoanStatus { 
        Active, 
        Current, 
        Delinquent30, 
        Delinquent60, 
        Delinquent90, 
        Default, 
        PaidOff, 
        RefinancedOut 
    }

    struct DSCRLoanData {
        uint256 loanId;
        uint256 productId;
        address borrower;
        uint256 originalPrincipal;
        uint256 principalOutstanding;
        uint256 interestRateBps;
        uint256 monthlyPayment;
        uint256 termMonths;
        uint256 paymentsRemaining;
        uint256 startTimestamp;
        uint256 lastPaymentTimestamp;
        uint256 totalInterestPaid;
        uint256 totalPrincipalPaid;
        uint256 appraisedValue;
        uint256 monthlyRent;
        uint256 dscrBps;
        uint256 ltvBps;
        DSCRLoanStatus status;
        bytes32 collateralHash;
    }

    function mintDSCRLoan(
        address borrower,
        uint256 productId,
        uint256 principal,
        uint256 appraisedValue,
        uint256 monthlyRent,
        uint256 monthlyPayment,
        uint256 interestRateBps,
        uint256 termMonths,
        uint256 dscrBps,
        uint256 ltvBps,
        bytes32 collateralHash
    ) external returns (uint256 loanId);

    function recordDSCRPayment(
        uint256 loanId,
        uint256 principalPortion,
        uint256 interestPortion
    ) external;

    function updateDSCRLoanStatus(uint256 loanId, DSCRLoanStatus status) external;
    function getDSCRLoansByBorrower(address borrower) external view returns (uint256[] memory);
    function setRefinancedOut(uint256 loanId, uint256 newLoanId) external;

    function getDSCRLoanCore(uint256 loanId) external view returns (
        uint256 loanId_,
        uint256 productId,
        address borrower,
        uint256 originalPrincipal,
        uint256 principalOutstanding,
        DSCRLoanStatus status
    );

    function getDSCRLoanTerms(uint256 loanId) external view returns (
        uint256 interestRateBps,
        uint256 monthlyPayment,
        uint256 termMonths,
        uint256 paymentsRemaining,
        uint256 dscrBps,
        uint256 ltvBps
    );

    function getDSCRLoanPayments(uint256 loanId) external view returns (
        uint256 startTimestamp,
        uint256 lastPaymentTimestamp,
        uint256 totalInterestPaid,
        uint256 totalPrincipalPaid
    );

    function getDSCRLoanProperty(uint256 loanId) external view returns (
        uint256 appraisedValue,
        uint256 monthlyRent,
        bytes32 collateralHash
    );

    event DSCRLoanOriginated(
        uint256 indexed loanId,
        address indexed borrower,
        uint256 principal,
        uint256 productId,
        uint256 dscrBps,
        uint256 ltvBps,
        uint256 monthlyPayment
    );
    event DSCRLoanPayment(
        uint256 indexed loanId,
        address indexed payer,
        uint256 principalPortion,
        uint256 interestPortion,
        uint256 principalRemaining
    );
    event DSCRLoanStatusChanged(uint256 indexed loanId, DSCRLoanStatus oldStatus, DSCRLoanStatus newStatus);
    event DSCRLoanRefinanced(uint256 indexed oldLoanId, uint256 indexed newLoanId);
}

interface IDSCRLoanManager {
    struct OriginateParams {
        address borrower;
        uint256 productId;
        uint256 principal;
        uint256 appraisedValue;
        uint256 monthlyRent;
        uint256 monthlyExpenses;
        bytes32 collateralHash;
    }

    function originate(OriginateParams calldata params) external returns (uint256 loanId);
    function payOnChain(uint256 loanId, uint256 amount) external;
    function postOffChainPayment(uint256 loanId, uint256 amount, bytes32 referenceHash) external;
    function refinanceFromFixFlip(
        uint256 fixFlipLoanId,
        uint256 newProductId,
        uint256 newPrincipal,
        uint256 appraisedValue,
        uint256 monthlyRent,
        uint256 monthlyExpenses,
        bytes32 collateralHash
    ) external returns (uint256 newLoanId);
    function computeMonthlyPayment(uint256 principal, uint256 aprBps, uint256 termMonths) external pure returns (uint256);
    function markDelinquent(uint256 loanId, IDSCRLoanReceipt.DSCRLoanStatus newStatus) external;
    function markDefault(uint256 loanId) external;

    event DSCRLoanFunded(
        uint256 indexed loanId,
        address indexed borrower,
        uint256 principal,
        uint256 productId,
        uint256 dscrBps,
        uint256 ltvBps
    );
    event PaymentReceived(
        uint256 indexed loanId,
        uint256 amount,
        uint256 principalPortion,
        uint256 interestPortion,
        bool isOnChain
    );
    event PaymentPosted(
        uint256 indexed loanId,
        uint256 amount,
        bytes32 indexed referenceHash,
        address indexed postedBy
    );
    event RefinanceCompleted(
        uint256 indexed oldLoanId,
        uint256 indexed newLoanId,
        uint256 payoffAmount,
        uint256 cashOut
    );
    event LoanDefaulted(uint256 indexed loanId, uint256 outstandingBalance);
}

contracts-axusd/realestate/FixFlipManage.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "./Interfaces.sol";

contract FixFlipManager is AccessControl, Pausable, ReentrancyGuard, IProductManager {
    using SafeERC20 for IERC20;

    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");
    bytes32 public constant UNDERWRITER_ROLE = keccak256("UNDERWRITER_ROLE");
    bytes32 public constant GUARDIAN_ROLE = keccak256("GUARDIAN_ROLE");

    uint256 public constant PRODUCT_ID = 1; // Fix & Flip = Product 1

    IERC20 public immutable axusd;
    IPoolVault public vault;
    ILoanReceipt public loanReceipt;
    IRiskConfig public riskConfig;
    IRepaymentRouter public repaymentRouter;

    bool public active;
    uint256 public totalOriginated;
    uint256 public totalRepaid;
    uint256 public activeLoans;

    mapping(uint256 => LoanDetails) public loanDetails;

    struct LoanDetails {
        uint256 purchasePrice;
        uint256 afterRepairValue;
        uint256 rehabBudget;
        address approvedBy;
        uint256 approvedAt;
        uint256 fundedAt;
        uint256 closedAt;
    }

    event LoanFunded(
        uint256 indexed loanId,
        address indexed borrower,
        uint256 principal,
        uint256 purchasePrice,
        uint256 arv
    );
    event LoanPaymentReceived(uint256 indexed loanId, uint256 amount, uint256 remaining);
    event LoanFullyRepaid(uint256 indexed loanId, uint256 totalPaid);
    event LoanDefaulted(uint256 indexed loanId);
    event ManagerActivated();
    event ManagerDeactivated();

    constructor(
        address _axusd,
        address _vault,
        address _loanReceipt,
        address _riskConfig,
        address _repaymentRouter
    ) {
        require(_axusd != address(0), "FixFlipManager: invalid axusd");
        require(_vault != address(0), "FixFlipManager: invalid vault");
        require(_loanReceipt != address(0), "FixFlipManager: invalid loanReceipt");
        require(_riskConfig != address(0), "FixFlipManager: invalid riskConfig");
        require(_repaymentRouter != address(0), "FixFlipManager: invalid router");

        axusd = IERC20(_axusd);
        vault = IPoolVault(_vault);
        loanReceipt = ILoanReceipt(_loanReceipt);
        riskConfig = IRiskConfig(_riskConfig);
        repaymentRouter = IRepaymentRouter(_repaymentRouter);
        active = true;

        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(ADMIN_ROLE, msg.sender);
        _grantRole(UNDERWRITER_ROLE, msg.sender);
        _grantRole(GUARDIAN_ROLE, msg.sender);
    }

    function productId() external pure override returns (uint256) {
        return PRODUCT_ID;
    }

    function isActive() external view override returns (bool) {
        return active && !paused();
    }

    function originate(
        address borrower,
        uint256 principal,
        IUnderwriter.DealTerms calldata terms
    ) external override onlyRole(UNDERWRITER_ROLE) nonReentrant whenNotPaused returns (uint256) {
        require(active, "FixFlipManager: not active");
        require(borrower != address(0), "FixFlipManager: invalid borrower");
        require(principal > 0, "FixFlipManager: zero principal");

        IRiskConfig.ProductRisk memory risk = riskConfig.getProductRisk(PRODUCT_ID);
        require(risk.active, "FixFlipManager: product not active");

        require(principal >= risk.minLoanSize, "FixFlipManager: below min loan size");
        require(principal <= risk.maxLoanSize, "FixFlipManager: exceeds max loan size");
        require(terms.termDays <= risk.maxTermDays, "FixFlipManager: term too long");

        uint256 maxLoan = (terms.afterRepairValue * risk.maxLtvBps) / 10000;
        require(principal <= maxLoan, "FixFlipManager: exceeds max LTV");

        require(
            vault.availableLiquidity() >= principal,
            "FixFlipManager: insufficient vault liquidity"
        );

        uint256 loanId = loanReceipt.mintLoan(
            borrower,
            PRODUCT_ID,
            principal,
            risk.interestRateBps,
            terms.termDays,
            terms.collateralHash
        );

        loanDetails[loanId] = LoanDetails({
            purchasePrice: terms.purchasePrice,
            afterRepairValue: terms.afterRepairValue,
            rehabBudget: terms.rehabBudget,
            approvedBy: msg.sender,
            approvedAt: block.timestamp,
            fundedAt: block.timestamp,
            closedAt: 0
        });

        vault.lockForLoan(principal);
        axusd.safeTransferFrom(address(vault), borrower, principal);

        totalOriginated += principal;
        activeLoans++;

        emit LoanFunded(
            loanId,
            borrower,
            principal,
            terms.purchasePrice,
            terms.afterRepairValue
        );

        return loanId;
    }

    function pay(uint256 loanId, uint256 amount) external override nonReentrant whenNotPaused {
        require(amount > 0, "FixFlipManager: zero amount");

        ILoanReceipt.LoanData memory loan = loanReceipt.getLoan(loanId);
        require(loan.loanId == loanId, "FixFlipManager: loan not found");
        require(
            loan.status == ILoanReceipt.LoanStatus.Active ||
            loan.status == ILoanReceipt.LoanStatus.Repaying,
            "FixFlipManager: loan not payable"
        );

        uint256 totalDue = loanReceipt.calculateTotalDue(loanId);
        uint256 interestDue = loanReceipt.calculateInterestDue(loanId);
        uint256 principalRemaining = loan.principal - loan.amountRepaid;

        uint256 interestPortion;
        uint256 principalPortion;

        if (amount >= totalDue) {
            amount = totalDue;
            interestPortion = interestDue;
            principalPortion = amount - interestPortion;
        } else if (amount <= interestDue) {
            interestPortion = amount;
            principalPortion = 0;
        } else {
            interestPortion = interestDue;
            principalPortion = amount - interestPortion;
        }

        axusd.safeTransferFrom(msg.sender, address(repaymentRouter), amount);
        repaymentRouter.routePayment(loanId, amount, principalPortion, interestPortion);

        uint256 newAmountRepaid = loan.amountRepaid + principalPortion;
        totalRepaid += principalPortion;

        if (newAmountRepaid >= loan.principal) {
            loanReceipt.updateLoanStatus(loanId, ILoanReceipt.LoanStatus.Repaid);
            loanDetails[loanId].closedAt = block.timestamp;
            activeLoans--;
            emit LoanFullyRepaid(loanId, newAmountRepaid);
        } else {
            loanReceipt.updateLoanStatus(loanId, ILoanReceipt.LoanStatus.Repaying);
            emit LoanPaymentReceived(loanId, amount, loan.principal - newAmountRepaid);
        }
    }

    function closeLoan(uint256 loanId) external override onlyRole(ADMIN_ROLE) {
        ILoanReceipt.LoanData memory loan = loanReceipt.getLoan(loanId);
        require(loan.loanId == loanId, "FixFlipManager: loan not found");
        require(
            loan.status == ILoanReceipt.LoanStatus.Repaid,
            "FixFlipManager: loan not fully repaid"
        );

        if (loanDetails[loanId].closedAt == 0) {
            loanDetails[loanId].closedAt = block.timestamp;
        }
    }

    function markDefaulted(uint256 loanId) external onlyRole(ADMIN_ROLE) {
        ILoanReceipt.LoanData memory loan = loanReceipt.getLoan(loanId);
        require(loan.loanId == loanId, "FixFlipManager: loan not found");
        require(
            loan.status == ILoanReceipt.LoanStatus.Active ||
            loan.status == ILoanReceipt.LoanStatus.Repaying,
            "FixFlipManager: invalid status for default"
        );
        require(
            block.timestamp > loan.maturityTimestamp + 30 days,
            "FixFlipManager: grace period not elapsed"
        );

        loanReceipt.updateLoanStatus(loanId, ILoanReceipt.LoanStatus.Defaulted);
        loanDetails[loanId].closedAt = block.timestamp;
        activeLoans--;

        emit LoanDefaulted(loanId);
    }

    function getLoanDetails(uint256 loanId) external view returns (
        ILoanReceipt.LoanData memory loan,
        LoanDetails memory details
    ) {
        loan = loanReceipt.getLoan(loanId);
        details = loanDetails[loanId];
    }

    function getStats() external view returns (
        uint256 _totalOriginated,
        uint256 _totalRepaid,
        uint256 _activeLoans,
        uint256 _availableLiquidity
    ) {
        return (totalOriginated, totalRepaid, activeLoans, vault.availableLiquidity());
    }

    function activate() external onlyRole(ADMIN_ROLE) {
        active = true;
        emit ManagerActivated();
    }

    function deactivate() external onlyRole(ADMIN_ROLE) {
        active = false;
        emit ManagerDeactivated();
    }

    function setVault(address _vault) external onlyRole(ADMIN_ROLE) {
        require(_vault != address(0), "FixFlipManager: invalid vault");
        vault = IPoolVault(_vault);
    }

    function setLoanReceipt(address _loanReceipt) external onlyRole(ADMIN_ROLE) {
        require(_loanReceipt != address(0), "FixFlipManager: invalid loanReceipt");
        loanReceipt = ILoanReceipt(_loanReceipt);
    }

    function setRiskConfig(address _riskConfig) external onlyRole(ADMIN_ROLE) {
        require(_riskConfig != address(0), "FixFlipManager: invalid riskConfig");
        riskConfig = IRiskConfig(_riskConfig);
    }

    function setRepaymentRouter(address _router) external onlyRole(ADMIN_ROLE) {
        require(_router != address(0), "FixFlipManager: invalid router");
        repaymentRouter = IRepaymentRouter(_router);
    }

    function pause() external onlyRole(GUARDIAN_ROLE) {
        _pause();
    }

    function unpause() external onlyRole(ADMIN_ROLE) {
        _unpause();
    }
}

contracts-axusd/realestate/FixFlipPoolVa.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/token/ERC20/extensions/ERC4626.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "./Interfaces.sol";

contract FixFlipPoolVault is ERC4626, AccessControl, Pausable, ReentrancyGuard, IPoolVault {
    using SafeERC20 for IERC20;

    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");
    bytes32 public constant MANAGER_ROLE = keccak256("MANAGER_ROLE");
    bytes32 public constant GUARDIAN_ROLE = keccak256("GUARDIAN_ROLE");

    uint256 private _lockedLiquidity;
    uint256 private _totalYieldAccumulated;

    uint256 public minDeposit;
    uint256 public maxDeposit;
    uint256 public withdrawalCooldown;

    mapping(address => uint256) public lastDepositTime;

    event ParametersUpdated(uint256 minDeposit, uint256 maxDeposit, uint256 cooldown);

    constructor(
        IERC20 _axusd,
        string memory name,
        string memory symbol
    ) ERC4626(_axusd) ERC20(name, symbol) {
        minDeposit = 100e18;
        maxDeposit = 1_000_000e18;
        withdrawalCooldown = 1 days;

        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(ADMIN_ROLE, msg.sender);
        _grantRole(MANAGER_ROLE, msg.sender);
        _grantRole(GUARDIAN_ROLE, msg.sender);
    }

    function deposit(uint256 assets, address receiver) 
        public 
        override(ERC4626, IPoolVault) 
        nonReentrant 
        whenNotPaused 
        returns (uint256) 
    {
        require(assets >= minDeposit, "FixFlipPoolVault: below min deposit");
        require(assets <= maxDeposit, "FixFlipPoolVault: above max deposit");

        lastDepositTime[receiver] = block.timestamp;
        uint256 shares = super.deposit(assets, receiver);

        emit PoolDeposit(receiver, assets, shares);
        return shares;
    }

    function withdraw(uint256 assets, address receiver, address owner)
        public
        override(ERC4626, IPoolVault)
        nonReentrant
        whenNotPaused
        returns (uint256)
    {
        require(
            block.timestamp >= lastDepositTime[owner] + withdrawalCooldown,
            "FixFlipPoolVault: cooldown not elapsed"
        );
        require(assets <= availableLiquidity(), "FixFlipPoolVault: insufficient liquidity");

        uint256 shares = super.withdraw(assets, receiver, owner);

        emit PoolWithdraw(receiver, assets, shares);
        return shares;
    }

    function redeem(uint256 shares, address receiver, address owner)
        public
        override(ERC4626, IPoolVault)
        nonReentrant
        whenNotPaused
        returns (uint256)
    {
        require(
            block.timestamp >= lastDepositTime[owner] + withdrawalCooldown,
            "FixFlipPoolVault: cooldown not elapsed"
        );

        uint256 assets = previewRedeem(shares);
        require(assets <= availableLiquidity(), "FixFlipPoolVault: insufficient liquidity");

        uint256 actualAssets = super.redeem(shares, receiver, owner);

        emit PoolWithdraw(receiver, actualAssets, shares);
        return actualAssets;
    }

    function lockForLoan(uint256 amount) external override onlyRole(MANAGER_ROLE) {
        require(amount <= availableLiquidity(), "FixFlipPoolVault: insufficient available liquidity");
        _lockedLiquidity += amount;
        emit FundsLocked(amount);
    }

    function unlockFromLoan(uint256 amount) external override onlyRole(MANAGER_ROLE) {
        require(amount <= _lockedLiquidity, "FixFlipPoolVault: amount exceeds locked");
        _lockedLiquidity -= amount;
        emit FundsUnlocked(amount);
    }

    function reportYield(uint256 amount) external override onlyRole(MANAGER_ROLE) {
        _totalYieldAccumulated += amount;
        emit YieldReported(amount);
    }

    function disburse(address recipient, uint256 amount) external override onlyRole(MANAGER_ROLE) {
        require(recipient != address(0), "FixFlipPoolVault: invalid recipient");
        require(amount <= IERC20(asset()).balanceOf(address(this)), "FixFlipPoolVault: insufficient balance");
        IERC20(asset()).safeTransfer(recipient, amount);
    }

    function totalAssets() public view override(ERC4626, IPoolVault) returns (uint256) {
        return IERC20(asset()).balanceOf(address(this)) + _lockedLiquidity;
    }

    function availableLiquidity() public view override returns (uint256) {
        uint256 balance = IERC20(asset()).balanceOf(address(this));
        return balance;
    }

    function lockedLiquidity() public view override returns (uint256) {
        return _lockedLiquidity;
    }

    function totalYieldAccumulated() external view returns (uint256) {
        return _totalYieldAccumulated;
    }

    function convertToShares(uint256 assets) public view override(ERC4626, IPoolVault) returns (uint256) {
        return super.convertToShares(assets);
    }

    function convertToAssets(uint256 shares) public view override(ERC4626, IPoolVault) returns (uint256) {
        return super.convertToAssets(shares);
    }

    function setParameters(
        uint256 _minDeposit,
        uint256 _maxDeposit,
        uint256 _cooldown
    ) external onlyRole(ADMIN_ROLE) {
        require(_maxDeposit > _minDeposit, "FixFlipPoolVault: invalid deposit range");
        minDeposit = _minDeposit;
        maxDeposit = _maxDeposit;
        withdrawalCooldown = _cooldown;
        emit ParametersUpdated(_minDeposit, _maxDeposit, _cooldown);
    }

    function pause() external onlyRole(GUARDIAN_ROLE) {
        _pause();
    }

    function unpause() external onlyRole(ADMIN_ROLE) {
        _unpause();
    }

    function emergencyWithdrawToken(
        address token,
        address to,
        uint256 amount
    ) external onlyRole(ADMIN_ROLE) {
        require(token != asset(), "FixFlipPoolVault: cannot withdraw base asset");
        IERC20(token).safeTransfer(to, amount);
    }
}

contracts-axusd/realestate/Interfaces.so.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC721/IERC721.sol";

interface IPoolVault {
    function deposit(uint256 assets, address receiver) external returns (uint256 shares);
    function withdraw(uint256 assets, address receiver, address owner) external returns (uint256 shares);
    function redeem(uint256 shares, address receiver, address owner) external returns (uint256 assets);
    function lockForLoan(uint256 amount) external;
    function unlockFromLoan(uint256 amount) external;
    function reportYield(uint256 amount) external;
    function disburse(address recipient, uint256 amount) external;
    function totalAssets() external view returns (uint256);
    function availableLiquidity() external view returns (uint256);
    function lockedLiquidity() external view returns (uint256);
    function convertToShares(uint256 assets) external view returns (uint256);
    function convertToAssets(uint256 shares) external view returns (uint256);

    event PoolDeposit(address indexed user, uint256 assets, uint256 shares);
    event PoolWithdraw(address indexed user, uint256 assets, uint256 shares);
    event YieldReported(uint256 amount);
    event FundsLocked(uint256 amount);
    event FundsUnlocked(uint256 amount);
}

interface IRiskConfig {
    struct ProductRisk {
        uint256 productId;
        uint256 maxLtvBps;
        uint256 maxTermDays;
        uint256 maxLoanSize;
        uint256 minLoanSize;
        uint256 originationFeeBps;
        uint256 interestRateBps;
        uint256 lateFeePerDayBps;
        uint256 insuranceReserveBps;
        uint256 protocolFeeBps;
        bool active;
    }

    function getProductRisk(uint256 productId) external view returns (ProductRisk memory);
    function setProductRisk(uint256 productId, ProductRisk calldata config) external;
    function isProductActive(uint256 productId) external view returns (bool);

    event ProductRiskUpdated(uint256 indexed productId, uint256 maxLtvBps, uint256 maxTermDays, uint256 maxLoanSize);
}

interface ILoanReceipt is IERC721 {
    enum LoanStatus { Active, Repaying, Repaid, Defaulted, Liquidated }

    struct LoanData {
        uint256 loanId;
        uint256 productId;
        address borrower;
        uint256 principal;
        uint256 interestRateBps;
        uint256 startTimestamp;
        uint256 maturityTimestamp;
        uint256 amountRepaid;
        LoanStatus status;
        bytes32 collateralHash;
    }

    function mintLoan(
        address borrower,
        uint256 productId,
        uint256 principal,
        uint256 interestRateBps,
        uint256 termDays,
        bytes32 collateralHash
    ) external returns (uint256 loanId);

    function updateLoanStatus(uint256 loanId, LoanStatus status) external;
    function recordPayment(uint256 loanId, uint256 amount) external;
    function getLoan(uint256 loanId) external view returns (LoanData memory);
    function getLoansByBorrower(address borrower) external view returns (uint256[] memory);
    function calculateInterestDue(uint256 loanId) external view returns (uint256);
    function calculateTotalDue(uint256 loanId) external view returns (uint256);

    event LoanOriginated(uint256 indexed loanId, address indexed borrower, uint256 principal, uint256 productId);
    event LoanPayment(uint256 indexed loanId, address indexed payer, uint256 amount);
    event LoanStatusChanged(uint256 indexed loanId, LoanStatus status);
    event LoanClosed(uint256 indexed loanId);
}

interface IRepaymentRouter {
    function routePayment(
        uint256 loanId,
        uint256 amount,
        uint256 principalPortion,
        uint256 interestPortion
    ) external;

    function getRoutingSplit(uint256 productId, uint256 interestAmount) external view returns (
        uint256 toVault,
        uint256 toInsurance,
        uint256 toTreasury
    );

    event PaymentRouted(
        uint256 indexed loanId,
        uint256 principal,
        uint256 yieldToVault,
        uint256 toInsurance,
        uint256 toTreasury
    );
}

interface IUnderwriter {
    struct DealTerms {
        uint256 purchasePrice;
        uint256 afterRepairValue;
        uint256 rehabBudget;
        uint256 termDays;
        bytes32 collateralHash;
    }

    function approveDeal(
        address borrower,
        uint256 productId,
        uint256 principal,
        DealTerms calldata terms
    ) external view returns (bool approved, string memory reason);
}

interface IProductManager {
    function productId() external view returns (uint256);
    function isActive() external view returns (bool);
    function originate(
        address borrower,
        uint256 principal,
        IUnderwriter.DealTerms calldata terms
    ) external returns (uint256 loanId);
    function pay(uint256 loanId, uint256 amount) external;
    function closeLoan(uint256 loanId) external;
}

interface IProductRegistry {
    function registerProduct(uint256 productId, address manager) external;
    function getManager(uint256 productId) external view returns (address);
    function isRegistered(uint256 productId) external view returns (bool);

    event ProductRegistered(uint256 indexed productId, address indexed manager);
}

contracts-axusd/realestate/LoanReceiptNF.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import "@openzeppelin/contracts/token/ERC721/extensions/ERC721Enumerable.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "./Interfaces.sol";

contract LoanReceiptNFT is ERC721Enumerable, AccessControl, Pausable, ILoanReceipt {
    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");
    bytes32 public constant MINTER_ROLE = keccak256("MINTER_ROLE");
    bytes32 public constant MANAGER_ROLE = keccak256("MANAGER_ROLE");

    uint256 private _nextLoanId = 1;

    mapping(uint256 => LoanData) private _loans;
    mapping(address => uint256[]) private _borrowerLoans;

    uint256 public constant SECONDS_PER_DAY = 86400;
    uint256 public constant BASIS_POINTS = 10000;
    uint256 public constant SECONDS_PER_YEAR = 365 days;

    constructor() ERC721("Axiom Loan Receipt", "AXLOAN") {
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(ADMIN_ROLE, msg.sender);
        _grantRole(MINTER_ROLE, msg.sender);
        _grantRole(MANAGER_ROLE, msg.sender);
    }

    function mintLoan(
        address borrower,
        uint256 productId,
        uint256 principal,
        uint256 interestRateBps,
        uint256 termDays,
        bytes32 collateralHash
    ) external override onlyRole(MINTER_ROLE) whenNotPaused returns (uint256 loanId) {
        require(borrower != address(0), "LoanReceiptNFT: zero borrower");
        require(principal > 0, "LoanReceiptNFT: zero principal");
        require(termDays > 0, "LoanReceiptNFT: zero term");

        loanId = _nextLoanId++;
        uint256 maturityTs = block.timestamp + (termDays * SECONDS_PER_DAY);

        _loans[loanId] = LoanData({
            loanId: loanId,
            productId: productId,
            borrower: borrower,
            principal: principal,
            interestRateBps: interestRateBps,
            startTimestamp: block.timestamp,
            maturityTimestamp: maturityTs,
            amountRepaid: 0,
            status: LoanStatus.Active,
            collateralHash: collateralHash
        });

        _borrowerLoans[borrower].push(loanId);
        _safeMint(borrower, loanId);

        emit LoanOriginated(loanId, borrower, principal, productId);
    }

    function updateLoanStatus(uint256 loanId, LoanStatus status) external override onlyRole(MANAGER_ROLE) {
        require(_exists(loanId), "LoanReceiptNFT: loan does not exist");
        require(_loans[loanId].status != LoanStatus.Repaid, "LoanReceiptNFT: loan already repaid");
        require(_loans[loanId].status != LoanStatus.Liquidated, "LoanReceiptNFT: loan already liquidated");

        _loans[loanId].status = status;
        emit LoanStatusChanged(loanId, status);

        if (status == LoanStatus.Repaid || status == LoanStatus.Liquidated) {
            emit LoanClosed(loanId);
        }
    }

    function recordPayment(uint256 loanId, uint256 amount) external override onlyRole(MANAGER_ROLE) {
        require(_exists(loanId), "LoanReceiptNFT: loan does not exist");
        require(amount > 0, "LoanReceiptNFT: zero payment");

        LoanData storage loan = _loans[loanId];
        require(loan.status == LoanStatus.Active || loan.status == LoanStatus.Repaying, "LoanReceiptNFT: loan not active");

        loan.amountRepaid += amount;

        if (loan.status == LoanStatus.Active) {
            loan.status = LoanStatus.Repaying;
            emit LoanStatusChanged(loanId, LoanStatus.Repaying);
        }

        emit LoanPayment(loanId, msg.sender, amount);
    }

    function getLoan(uint256 loanId) external view override returns (LoanData memory) {
        require(_exists(loanId), "LoanReceiptNFT: loan does not exist");
        return _loans[loanId];
    }

    function getLoansByBorrower(address borrower) external view override returns (uint256[] memory) {
        return _borrowerLoans[borrower];
    }

    function calculateInterestDue(uint256 loanId) public view override returns (uint256) {
        require(_exists(loanId), "LoanReceiptNFT: loan does not exist");
        LoanData memory loan = _loans[loanId];

        uint256 elapsed = block.timestamp - loan.startTimestamp;
        uint256 interest = (loan.principal * loan.interestRateBps * elapsed) / (BASIS_POINTS * SECONDS_PER_YEAR);
        return interest;
    }

    function calculateTotalDue(uint256 loanId) external view override returns (uint256) {
        require(_exists(loanId), "LoanReceiptNFT: loan does not exist");
        LoanData memory loan = _loans[loanId];

        uint256 interest = calculateInterestDue(loanId);
        uint256 totalDue = loan.principal + interest;

        if (loan.amountRepaid >= totalDue) {
            return 0;
        }
        return totalDue - loan.amountRepaid;
    }

    function isOverdue(uint256 loanId) external view returns (bool) {
        require(_exists(loanId), "LoanReceiptNFT: loan does not exist");
        LoanData memory loan = _loans[loanId];
        return block.timestamp > loan.maturityTimestamp && 
               loan.status != LoanStatus.Repaid && 
               loan.status != LoanStatus.Liquidated;
    }

    function _exists(uint256 tokenId) internal view returns (bool) {
        return tokenId > 0 && tokenId < _nextLoanId;
    }

    function pause() external onlyRole(ADMIN_ROLE) {
        _pause();
    }

    function unpause() external onlyRole(ADMIN_ROLE) {
        _unpause();
    }

    function supportsInterface(bytes4 interfaceId)
        public
        view
        override(ERC721Enumerable, AccessControl, IERC165)
        returns (bool)
    {
        return super.supportsInterface(interfaceId);
    }
}

