// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "./Interfaces.sol";

contract ProductRegistry is AccessControl, IProductRegistry {
    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");

    mapping(uint256 => address) private _managers;
    uint256[] private _productIds;

    event ProductDeregistered(uint256 indexed productId);
    event ProductManagerUpdated(uint256 indexed productId, address indexed oldManager, address indexed newManager);

    constructor() {
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(ADMIN_ROLE, msg.sender);
    }

    function registerProduct(
        uint256 productId,
        address manager
    ) external override onlyRole(ADMIN_ROLE) {
        require(manager != address(0), "ProductRegistry: invalid manager");
        require(!isRegistered(productId), "ProductRegistry: already registered");

        _managers[productId] = manager;
        _productIds.push(productId);

        emit ProductRegistered(productId, manager);
    }

    function updateManager(
        uint256 productId,
        address newManager
    ) external onlyRole(ADMIN_ROLE) {
        require(newManager != address(0), "ProductRegistry: invalid manager");
        require(isRegistered(productId), "ProductRegistry: not registered");

        address old = _managers[productId];
        _managers[productId] = newManager;

        emit ProductManagerUpdated(productId, old, newManager);
    }

    function deregisterProduct(uint256 productId) external onlyRole(ADMIN_ROLE) {
        require(isRegistered(productId), "ProductRegistry: not registered");

        delete _managers[productId];

        for (uint256 i = 0; i < _productIds.length; i++) {
            if (_productIds[i] == productId) {
                _productIds[i] = _productIds[_productIds.length - 1];
                _productIds.pop();
                break;
            }
        }

        emit ProductDeregistered(productId);
    }

    function getManager(uint256 productId) external view override returns (address) {
        return _managers[productId];
    }

    function isRegistered(uint256 productId) public view override returns (bool) {
        return _managers[productId] != address(0);
    }

    function getAllProducts() external view returns (uint256[] memory) {
        return _productIds;
    }

    function getProductCount() external view returns (uint256) {
        return _productIds.length;
    }

    function getProductInfo(uint256 productId) external view returns (
        address manager,
        bool registered,
        bool active
    ) {
        manager = _managers[productId];
        registered = manager != address(0);

        if (registered) {
            try IProductManager(manager).isActive() returns (bool _active) {
                active = _active;
            } catch {
                active = false;
            }
        }
    }
}

contracts-axusd/realestate/RepaymentRout.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "./Interfaces.sol";

contract RepaymentRouter is AccessControl, Pausable, ReentrancyGuard, IRepaymentRouter {
    using SafeERC20 for IERC20;

    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");
    bytes32 public constant MANAGER_ROLE = keccak256("MANAGER_ROLE");
    bytes32 public constant GUARDIAN_ROLE = keccak256("GUARDIAN_ROLE");

    IERC20 public immutable axusd;
    IPoolVault public vault;
    IRiskConfig public riskConfig;
    ILoanReceipt public loanReceipt;

    address public insuranceFund;
    address public treasury;

    uint256 public totalPrincipalRouted;
    uint256 public totalInterestRouted;
    uint256 public totalToInsurance;
    uint256 public totalToTreasury;

    event VaultUpdated(address indexed oldVault, address indexed newVault);
    event InsuranceFundUpdated(address indexed oldFund, address indexed newFund);
    event TreasuryUpdated(address indexed oldTreasury, address indexed newTreasury);

    constructor(
        address _axusd,
        address _vault,
        address _riskConfig,
        address _loanReceipt,
        address _insuranceFund,
        address _treasury
    ) {
        require(_axusd != address(0), "RepaymentRouter: invalid axusd");
        require(_vault != address(0), "RepaymentRouter: invalid vault");
        require(_riskConfig != address(0), "RepaymentRouter: invalid riskConfig");
        require(_insuranceFund != address(0), "RepaymentRouter: invalid insurance");
        require(_treasury != address(0), "RepaymentRouter: invalid treasury");

        axusd = IERC20(_axusd);
        vault = IPoolVault(_vault);
        riskConfig = IRiskConfig(_riskConfig);
        loanReceipt = ILoanReceipt(_loanReceipt);
        insuranceFund = _insuranceFund;
        treasury = _treasury;

        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(ADMIN_ROLE, msg.sender);
        _grantRole(MANAGER_ROLE, msg.sender);
        _grantRole(GUARDIAN_ROLE, msg.sender);
    }

    function routePayment(
        uint256 loanId,
        uint256 amount,
        uint256 principalPortion,
        uint256 interestPortion
    ) external override onlyRole(MANAGER_ROLE) nonReentrant whenNotPaused {
        require(amount > 0, "RepaymentRouter: zero amount");
        require(
            principalPortion + interestPortion == amount,
            "RepaymentRouter: amount mismatch"
        );

        ILoanReceipt.LoanData memory loan = loanReceipt.getLoan(loanId);
        require(loan.loanId == loanId, "RepaymentRouter: loan not found");

        axusd.safeTransferFrom(msg.sender, address(this), amount);

        if (principalPortion > 0) {
            axusd.safeTransfer(address(vault), principalPortion);
            vault.unlockFromLoan(principalPortion);
            totalPrincipalRouted += principalPortion;
        }

        uint256 yieldToVault = 0;
        uint256 toInsurance = 0;
        uint256 toProtocol = 0;

        if (interestPortion > 0) {
            (yieldToVault, toInsurance, toProtocol) = getRoutingSplit(
                loan.productId,
                interestPortion
            );

            if (yieldToVault > 0) {
                axusd.safeTransfer(address(vault), yieldToVault);
                vault.reportYield(yieldToVault);
            }

            if (toInsurance > 0) {
                axusd.safeTransfer(insuranceFund, toInsurance);
                totalToInsurance += toInsurance;
            }

            if (toProtocol > 0) {
                axusd.safeTransfer(treasury, toProtocol);
                totalToTreasury += toProtocol;
            }

            totalInterestRouted += interestPortion;
        }

        loanReceipt.recordPayment(loanId, amount);

        emit PaymentRouted(
            loanId,
            principalPortion,
            yieldToVault,
            toInsurance,
            toProtocol
        );
    }

    function getRoutingSplit(
        uint256 productId,
        uint256 interestAmount
    ) public view override returns (
        uint256 toVault,
        uint256 toInsurance,
        uint256 toTreasury
    ) {
        IRiskConfig.ProductRisk memory risk = riskConfig.getProductRisk(productId);

        uint256 insuranceBps = risk.insuranceReserveBps;
        uint256 protocolBps = risk.protocolFeeBps;

        toInsurance = (interestAmount * insuranceBps) / 10000;
        toTreasury = (interestAmount * protocolBps) / 10000;
        toVault = interestAmount - toInsurance - toTreasury;

        return (toVault, toInsurance, toTreasury);
    }

    function setVault(address _vault) external onlyRole(ADMIN_ROLE) {
        require(_vault != address(0), "RepaymentRouter: invalid vault");
        address old = address(vault);
        vault = IPoolVault(_vault);
        emit VaultUpdated(old, _vault);
    }

    function setInsuranceFund(address _insuranceFund) external onlyRole(ADMIN_ROLE) {
        require(_insuranceFund != address(0), "RepaymentRouter: invalid address");
        address old = insuranceFund;
        insuranceFund = _insuranceFund;
        emit InsuranceFundUpdated(old, _insuranceFund);
    }

    function setTreasury(address _treasury) external onlyRole(ADMIN_ROLE) {
        require(_treasury != address(0), "RepaymentRouter: invalid address");
        address old = treasury;
        treasury = _treasury;
        emit TreasuryUpdated(old, _treasury);
    }

    function setLoanReceipt(address _loanReceipt) external onlyRole(ADMIN_ROLE) {
        require(_loanReceipt != address(0), "RepaymentRouter: invalid address");
        loanReceipt = ILoanReceipt(_loanReceipt);
    }

    function setRiskConfig(address _riskConfig) external onlyRole(ADMIN_ROLE) {
        require(_riskConfig != address(0), "RepaymentRouter: invalid address");
        riskConfig = IRiskConfig(_riskConfig);
    }

    function getStats() external view returns (
        uint256 _totalPrincipalRouted,
        uint256 _totalInterestRouted,
        uint256 _totalToInsurance,
        uint256 _totalToTreasury
    ) {
        return (totalPrincipalRouted, totalInterestRouted, totalToInsurance, totalToTreasury);
    }

    function pause() external onlyRole(GUARDIAN_ROLE) {
        _pause();
    }

    function unpause() external onlyRole(ADMIN_ROLE) {
        _unpause();
    }

    function emergencyWithdraw(
        address token,
        address to,
        uint256 amount
    ) external onlyRole(ADMIN_ROLE) {
        IERC20(token).safeTransfer(to, amount);
    }
}

contracts-axusd/realestate/RiskConfig.so.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "./Interfaces.sol";

contract RiskConfig is AccessControl, IRiskConfig {
    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");
    bytes32 public constant RISK_MANAGER_ROLE = keccak256("RISK_MANAGER_ROLE");

    uint256 public constant MAX_LTV_CAP = 9000;
    uint256 public constant MAX_TERM_CAP = 365;
    uint256 public constant BASIS_POINTS = 10000;

    mapping(uint256 => ProductRisk) private _productRisks;
    uint256[] public productIds;

    constructor() {
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(ADMIN_ROLE, msg.sender);
        _grantRole(RISK_MANAGER_ROLE, msg.sender);
    }

    function setProductRisk(
        uint256 productId,
        ProductRisk calldata config
    ) external override onlyRole(RISK_MANAGER_ROLE) {
        require(config.maxLtvBps > 0 && config.maxLtvBps <= MAX_LTV_CAP, "RiskConfig: invalid LTV");
        require(config.maxTermDays > 0 && config.maxTermDays <= MAX_TERM_CAP, "RiskConfig: invalid term");
        require(config.maxLoanSize > config.minLoanSize, "RiskConfig: invalid loan size range");
        require(config.interestRateBps > 0, "RiskConfig: zero interest rate");
        require(
            config.insuranceReserveBps + config.protocolFeeBps <= BASIS_POINTS,
            "RiskConfig: fee split exceeds 100%"
        );

        bool isNew = _productRisks[productId].productId == 0;
        _productRisks[productId] = config;
        _productRisks[productId].productId = productId;

        if (isNew) {
            productIds.push(productId);
        }

        emit ProductRiskUpdated(
            productId,
            config.maxLtvBps,
            config.maxTermDays,
            config.maxLoanSize
        );
    }

    function getProductRisk(uint256 productId) external view override returns (ProductRisk memory) {
        require(_productRisks[productId].productId != 0, "RiskConfig: product not found");
        return _productRisks[productId];
    }

    function isProductActive(uint256 productId) external view override returns (bool) {
        return _productRisks[productId].active;
    }

    function deactivateProduct(uint256 productId) external onlyRole(ADMIN_ROLE) {
        require(_productRisks[productId].productId != 0, "RiskConfig: product not found");
        _productRisks[productId].active = false;
        emit ProductRiskUpdated(productId, 0, 0, 0);
    }

    function activateProduct(uint256 productId) external onlyRole(ADMIN_ROLE) {
        require(_productRisks[productId].productId != 0, "RiskConfig: product not found");
        _productRisks[productId].active = true;
        emit ProductRiskUpdated(
            productId,
            _productRisks[productId].maxLtvBps,
            _productRisks[productId].maxTermDays,
            _productRisks[productId].maxLoanSize
        );
    }

    function getProductCount() external view returns (uint256) {
        return productIds.length;
    }

    function getAllProductIds() external view returns (uint256[] memory) {
        return productIds;
    }
}

