// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "../interfaces/IVaultEngine.sol";
import "../interfaces/IAxiomStable.sol";
import "../lib/VaultMath.sol";

contract Liquidator is AccessControl, ReentrancyGuard {
    using SafeERC20 for IERC20;

    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");
    bytes32 public constant KEEPER_ROLE = keccak256("KEEPER_ROLE");

    IVaultEngine public immutable vaultEngine;
    IAxiomStable public immutable axusd;

    bool public permissionless;
    uint256 public keeperBonus;
    uint256 public maxBatchSize;

    mapping(address => uint256) private _lastLiquidationBlock;

    event LiquidationExecuted(
        address indexed owner,
        address indexed collateral,
        address indexed keeper,
        uint256 debtCovered,
        uint256 collateralSeized,
        uint256 bonus
    );
    event PermissionlessToggled(bool enabled);
    event KeeperBonusUpdated(uint256 newBonus);

    constructor(address _vaultEngine, address _axusd) {
        require(_vaultEngine != address(0), "Liquidator: zero vault engine");
        require(_axusd != address(0), "Liquidator: zero axusd");

        vaultEngine = IVaultEngine(_vaultEngine);
        axusd = IAxiomStable(_axusd);
        permissionless = true;
        keeperBonus = 50;
        maxBatchSize = 10;

        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(ADMIN_ROLE, msg.sender);
    }

    function liquidate(
        address owner,
        address collateral,
        uint256 maxDebtToCover
    ) external nonReentrant {
        if (!permissionless) {
            require(hasRole(KEEPER_ROLE, msg.sender), "Liquidator: not keeper");
        }

        require(vaultEngine.isLiquidatable(owner, collateral), "Liquidator: not liquidatable");

        IVaultEngine.Vault memory vault = vaultEngine.getVault(owner, collateral);
        require(vault.debtAmount > 0, "Liquidator: no debt");

        uint256 maxAllowed = (vault.debtAmount * 5000) / 10000;
        uint256 debtToCover = VaultMath.min(maxDebtToCover, maxAllowed);
        debtToCover = VaultMath.min(debtToCover, vault.debtAmount);

        require(IERC20(address(axusd)).balanceOf(msg.sender) >= debtToCover, "Liquidator: insufficient AXUSD");

        IERC20(address(axusd)).safeTransferFrom(msg.sender, address(this), debtToCover);
        IERC20(address(axusd)).approve(address(vaultEngine), debtToCover);

        uint256 collateralBefore = IERC20(collateral).balanceOf(address(this));

        IVaultEngine(address(vaultEngine)).liquidate(owner, collateral, debtToCover);

        uint256 collateralAfter = IERC20(collateral).balanceOf(address(this));
        uint256 collateralReceived = collateralAfter - collateralBefore;

        require(collateralReceived > 0, "Liquidator: no collateral received");

        IERC20(collateral).safeTransfer(msg.sender, collateralReceived);

        uint256 bonus = (collateralReceived * keeperBonus) / 10000;

        emit LiquidationExecuted(owner, collateral, msg.sender, debtToCover, collateralReceived, bonus);
    }

    function batchLiquidate(
        address[] calldata owners,
        address[] calldata collaterals,
        uint256[] calldata maxDebts
    ) external nonReentrant {
        require(owners.length == collaterals.length, "Liquidator: length mismatch");
        require(owners.length == maxDebts.length, "Liquidator: length mismatch");
        require(owners.length <= maxBatchSize, "Liquidator: batch too large");

        for (uint256 i = 0; i < owners.length; i++) {
            if (vaultEngine.isLiquidatable(owners[i], collaterals[i])) {
                try this.liquidateSingle(owners[i], collaterals[i], maxDebts[i]) {
                } catch {
                }
            }
        }
    }

    function setMaxBatchSize(uint256 newSize) external onlyRole(ADMIN_ROLE) {
        require(newSize > 0 && newSize <= 50, "Liquidator: invalid batch size");
        maxBatchSize = newSize;
    }

    function liquidateSingle(
        address owner,
        address collateral,
        uint256 maxDebt
    ) external {
        require(msg.sender == address(this), "Liquidator: internal only");

        IVaultEngine.Vault memory vault = vaultEngine.getVault(owner, collateral);
        uint256 maxAllowed = (vault.debtAmount * 5000) / 10000;
        uint256 debtToCover = VaultMath.min(maxDebt, maxAllowed);

        IVaultEngine(address(vaultEngine)).liquidate(owner, collateral, debtToCover);
    }

    function setPermissionless(bool enabled) external onlyRole(ADMIN_ROLE) {
        permissionless = enabled;
        emit PermissionlessToggled(enabled);
    }

    function setKeeperBonus(uint256 newBonus) external onlyRole(ADMIN_ROLE) {
        require(newBonus <= 500, "Liquidator: bonus too high");
        keeperBonus = newBonus;
        emit KeeperBonusUpdated(newBonus);
    }

    function getLiquidatableVaults(
        address[] calldata owners,
        address[] calldata collaterals
    ) external view returns (bool[] memory) {
        require(owners.length == collaterals.length, "Liquidator: length mismatch");

        bool[] memory results = new bool[](owners.length);
        for (uint256 i = 0; i < owners.length; i++) {
            results[i] = vaultEngine.isLiquidatable(owners[i], collaterals[i]);
        }
        return results;
    }

    function rescueTokens(address token, uint256 amount) external onlyRole(ADMIN_ROLE) {
        IERC20(token).safeTransfer(msg.sender, amount);
    }
}

contracts-axusd/stablecoin/core/MarketOp.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "../interfaces/IAxiomStable.sol";
import "../interfaces/IBackstopVault.sol";
import "../interfaces/IMarketOperations.sol";

interface IUniswapV2Router {
    function swapExactTokensForTokens(
        uint256 amountIn,
        uint256 amountOutMin,
        address[] calldata path,
        address to,
        uint256 deadline
    ) external returns (uint256[] memory amounts);

    function addLiquidity(
        address tokenA,
        address tokenB,
        uint256 amountADesired,
        uint256 amountBDesired,
        uint256 amountAMin,
        uint256 amountBMin,
        address to,
        uint256 deadline
    ) external returns (uint256 amountA, uint256 amountB, uint256 liquidity);

    function removeLiquidity(
        address tokenA,
        address tokenB,
        uint256 liquidity,
        uint256 amountAMin,
        uint256 amountBMin,
        address to,
        uint256 deadline
    ) external returns (uint256 amountA, uint256 amountB);

    function getAmountsOut(uint256 amountIn, address[] calldata path) external view returns (uint256[] memory amounts);
}

interface IUniswapV2Pair {
    function getReserves() external view returns (uint112 reserve0, uint112 reserve1, uint32 blockTimestampLast);
    function token0() external view returns (address);
    function token1() external view returns (address);
}

contract MarketOperations is AccessControl, ReentrancyGuard, Pausable, IMarketOperations {
    using SafeERC20 for IERC20;

    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");
    bytes32 public constant OPERATOR_ROLE = keccak256("OPERATOR_ROLE");
    bytes32 public constant GUARDIAN_ROLE = keccak256("GUARDIAN_ROLE");

    IAxiomStable public immutable axusd;
    IERC20 public immutable collateral;
    IUniswapV2Router public immutable router;
    IUniswapV2Pair public immutable pair;
    IBackstopVault public backstopVault;

    uint256 public lowerPegBound;
    uint256 public upperPegBound;
    uint256 public constant PRECISION = 1e18;
    uint256 public constant PEG_TARGET = 1e18;

    uint256 public dailyBuyLimit;
    uint256 public dailySellLimit;
    uint256 public dailyBuyUsed;
    uint256 public dailySellUsed;
    uint256 public lastResetTimestamp;

    bool public axusdIsToken0;

    event DailyLimitsUpdated(uint256 buyLimit, uint256 sellLimit);
    event BackstopVaultUpdated(address indexed newVault);

    constructor(
        address _axusd,
        address _collateral,
        address _router,
        address _pair,
        uint256 _lowerBound,
        uint256 _upperBound,
        uint256 _dailyBuyLimit,
        uint256 _dailySellLimit
    ) {
        require(_axusd != address(0), "MarketOps: zero axusd");
        require(_collateral != address(0), "MarketOps: zero collateral");
        require(_router != address(0), "MarketOps: zero router");
        require(_pair != address(0), "MarketOps: zero pair");
        require(_lowerBound < PEG_TARGET, "MarketOps: invalid lower bound");
        require(_upperBound > PEG_TARGET, "MarketOps: invalid upper bound");

        axusd = IAxiomStable(_axusd);
        collateral = IERC20(_collateral);
        router = IUniswapV2Router(_router);
        pair = IUniswapV2Pair(_pair);

        lowerPegBound = _lowerBound;
        upperPegBound = _upperBound;
        dailyBuyLimit = _dailyBuyLimit;
        dailySellLimit = _dailySellLimit;
        lastResetTimestamp = block.timestamp;

        axusdIsToken0 = pair.token0() == _axusd;

        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(ADMIN_ROLE, msg.sender);
        _grantRole(GUARDIAN_ROLE, msg.sender);
    }

    function _resetDailyLimitsIfNeeded() internal {
        if (block.timestamp >= lastResetTimestamp + 1 days) {
            dailyBuyUsed = 0;
            dailySellUsed = 0;
            lastResetTimestamp = block.timestamp;
        }
    }

    function defendPegBuy(
        uint256 axusdAmount,
        uint256 minCollateralOut
    ) external override nonReentrant whenNotPaused onlyRole(OPERATOR_ROLE) {
        require(axusdAmount > 0, "MarketOps: zero amount");

        uint256 currentPrice = getCurrentPrice();
        require(currentPrice > upperPegBound, "MarketOps: peg not above bound");

        _resetDailyLimitsIfNeeded();
        require(dailyBuyUsed + axusdAmount <= dailyBuyLimit, "MarketOps: daily buy limit");

        axusd.mint(address(this), axusdAmount);

        IERC20(address(axusd)).approve(address(router), axusdAmount);

        address[] memory path = new address[](2);
        path[0] = address(axusd);
        path[1] = address(collateral);

        uint256[] memory amounts = router.swapExactTokensForTokens(
            axusdAmount,
            minCollateralOut,
            path,
            address(this),
            block.timestamp + 300
        );

        dailyBuyUsed += axusdAmount;

        uint256 newPrice = getCurrentPrice();
        emit PegDefenseExecuted(axusdAmount, amounts[1], newPrice);
    }

    function defendPegSell(
        uint256 collateralAmount,
        uint256 minAxusdOut
    ) external override nonReentrant whenNotPaused onlyRole(OPERATOR_ROLE) {
        require(collateralAmount > 0, "MarketOps: zero amount");

        uint256 currentPrice = getCurrentPrice();
        require(currentPrice < lowerPegBound, "MarketOps: peg not below bound");

        _resetDailyLimitsIfNeeded();
        require(dailySellUsed + collateralAmount <= dailySellLimit, "MarketOps: daily sell limit");

        require(collateral.balanceOf(address(this)) >= collateralAmount, "MarketOps: insufficient collateral");

        collateral.approve(address(router), collateralAmount);

        address[] memory path = new address[](2);
        path[0] = address(collateral);
        path[1] = address(axusd);

        uint256[] memory amounts = router.swapExactTokensForTokens(
            collateralAmount,
            minAxusdOut,
            path,
            address(this),
            block.timestamp + 300
        );

        axusd.burn(address(this), amounts[1]);

        dailySellUsed += collateralAmount;

        uint256 newPrice = getCurrentPrice();
        emit PegDefenseExecuted(amounts[1], collateralAmount, newPrice);
    }

    function provideLiquidity(
        uint256 axusdAmount,
        uint256 collateralAmount,
        uint256 minLpTokens
    ) external override nonReentrant whenNotPaused onlyRole(OPERATOR_ROLE) {
        require(axusdAmount > 0 && collateralAmount > 0, "MarketOps: zero amounts");

        axusd.mint(address(this), axusdAmount);

        require(collateral.balanceOf(address(this)) >= collateralAmount, "MarketOps: insufficient collateral");

        IERC20(address(axusd)).approve(address(router), axusdAmount);
        collateral.approve(address(router), collateralAmount);

        (uint256 amountA, uint256 amountB, uint256 liquidity) = router.addLiquidity(
            address(axusd),
            address(collateral),
            axusdAmount,
            collateralAmount,
            (axusdAmount * 95) / 100,
            (collateralAmount * 95) / 100,
            address(this),
            block.timestamp + 300
        );

        require(liquidity >= minLpTokens, "MarketOps: insufficient LP");

        emit LiquidityProvided(address(pair), amountA, amountB);
    }

    function removeLiquidity(
        uint256 lpTokens,
        uint256 minAxusd,
        uint256 minCollateral
    ) external override nonReentrant whenNotPaused onlyRole(OPERATOR_ROLE) {
        require(lpTokens > 0, "MarketOps: zero LP tokens");

        IERC20(address(pair)).approve(address(router), lpTokens);

        (uint256 amountAxusd, uint256 amountCollateral) = router.removeLiquidity(
            address(axusd),
            address(collateral),
            lpTokens,
            minAxusd,
            minCollateral,
            address(this),
            block.timestamp + 300
        );

        axusd.burn(address(this), amountAxusd);

        emit LiquidityRemoved(address(pair), lpTokens);
    }

    function getCurrentPrice() public view override returns (uint256) {
        (uint112 reserve0, uint112 reserve1, ) = pair.getReserves();

        if (reserve0 == 0 || reserve1 == 0) return PEG_TARGET;

        if (axusdIsToken0) {
            return (uint256(reserve1) * PRECISION) / uint256(reserve0);
        } else {
            return (uint256(reserve0) * PRECISION) / uint256(reserve1);
        }
    }

    function isPegDefenseNeeded() external view override returns (bool) {
        uint256 price = getCurrentPrice();
        return price < lowerPegBound || price > upperPegBound;
    }

    function setPriceThresholds(uint256 _lowerBound, uint256 _upperBound) external onlyRole(ADMIN_ROLE) {
        require(_lowerBound < PEG_TARGET, "MarketOps: invalid lower");
        require(_upperBound > PEG_TARGET, "MarketOps: invalid upper");
        lowerPegBound = _lowerBound;
        upperPegBound = _upperBound;
        emit PriceThresholdUpdated(_lowerBound, _upperBound);
    }

    function setDailyLimits(uint256 _buyLimit, uint256 _sellLimit) external onlyRole(ADMIN_ROLE) {
        dailyBuyLimit = _buyLimit;
        dailySellLimit = _sellLimit;
        emit DailyLimitsUpdated(_buyLimit, _sellLimit);
    }

    function setBackstopVault(address _vault) external onlyRole(ADMIN_ROLE) {
        require(_vault != address(0), "MarketOps: zero vault");
        backstopVault = IBackstopVault(_vault);
        emit BackstopVaultUpdated(_vault);
    }

    function withdrawCollateral(address recipient, uint256 amount) external onlyRole(ADMIN_ROLE) {
        require(recipient != address(0), "MarketOps: zero recipient");
        collateral.safeTransfer(recipient, amount);
    }

    function getRemainingLimits() external view returns (uint256 buyRemaining, uint256 sellRemaining) {
        if (block.timestamp >= lastResetTimestamp + 1 days) {
            return (dailyBuyLimit, dailySellLimit);
        }
        buyRemaining = dailyBuyLimit > dailyBuyUsed ? dailyBuyLimit - dailyBuyUsed : 0;
        sellRemaining = dailySellLimit > dailySellUsed ? dailySellLimit - dailySellUsed : 0;
    }

    function pause() external onlyRole(GUARDIAN_ROLE) {
        _pause();
    }

    function unpause() external onlyRole(ADMIN_ROLE) {
        _unpause();
    }
}

