// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "../interfaces/IRateLimiter.sol";

contract RateLimiter is AccessControl, IRateLimiter {
    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");
    bytes32 public constant RECORDER_ROLE = keccak256("RECORDER_ROLE");

    uint256 public dailyMintLimit;
    uint256 public perAddressDailyLimit;
    uint256 public currentDayMinted;
    uint256 public lastResetTimestamp;

    mapping(address => uint256) public addressDailyMinted;
    mapping(address => uint256) public addressLastReset;

    event DailyLimitUpdated(uint256 newLimit);
    event PerAddressLimitUpdated(uint256 newLimit);
    event MintRecorded(address indexed user, uint256 amount, uint256 userTotal, uint256 globalTotal);
    event DailyReset(uint256 timestamp);

    constructor(uint256 _dailyMintLimit, uint256 _perAddressDailyLimit) {
        require(_dailyMintLimit > 0, "RateLimiter: zero daily limit");
        require(_perAddressDailyLimit > 0, "RateLimiter: zero per-address limit");
        require(_perAddressDailyLimit <= _dailyMintLimit, "RateLimiter: per-address exceeds daily");

        dailyMintLimit = _dailyMintLimit;
        perAddressDailyLimit = _perAddressDailyLimit;
        lastResetTimestamp = block.timestamp;

        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(ADMIN_ROLE, msg.sender);
    }

    function _resetIfNeeded() internal {
        if (block.timestamp >= lastResetTimestamp + 1 days) {
            currentDayMinted = 0;
            lastResetTimestamp = block.timestamp;
            emit DailyReset(block.timestamp);
        }
    }

    function _resetAddressIfNeeded(address user) internal {
        if (block.timestamp >= addressLastReset[user] + 1 days) {
            addressDailyMinted[user] = 0;
            addressLastReset[user] = block.timestamp;
        }
    }

    function checkMintLimit(address user, uint256 amount) external view override returns (bool) {
        uint256 effectiveGlobalMinted = currentDayMinted;
        if (block.timestamp >= lastResetTimestamp + 1 days) {
            effectiveGlobalMinted = 0;
        }

        uint256 effectiveUserMinted = addressDailyMinted[user];
        if (block.timestamp >= addressLastReset[user] + 1 days) {
            effectiveUserMinted = 0;
        }

        if (effectiveGlobalMinted + amount > dailyMintLimit) return false;
        if (effectiveUserMinted + amount > perAddressDailyLimit) return false;

        return true;
    }

    function recordMint(address user, uint256 amount) external override onlyRole(RECORDER_ROLE) {
        _resetIfNeeded();
        _resetAddressIfNeeded(user);

        require(currentDayMinted + amount <= dailyMintLimit, "RateLimiter: global limit exceeded");
        require(addressDailyMinted[user] + amount <= perAddressDailyLimit, "RateLimiter: address limit exceeded");

        currentDayMinted += amount;
        addressDailyMinted[user] += amount;

        emit MintRecorded(user, amount, addressDailyMinted[user], currentDayMinted);
    }

    function resetDailyLimits() external override onlyRole(ADMIN_ROLE) {
        currentDayMinted = 0;
        lastResetTimestamp = block.timestamp;
        emit DailyReset(block.timestamp);
    }

    function setDailyMintLimit(uint256 newLimit) external onlyRole(ADMIN_ROLE) {
        require(newLimit > 0, "RateLimiter: zero limit");
        require(newLimit >= perAddressDailyLimit, "RateLimiter: less than per-address");
        dailyMintLimit = newLimit;
        emit DailyLimitUpdated(newLimit);
    }

    function setPerAddressDailyLimit(uint256 newLimit) external onlyRole(ADMIN_ROLE) {
        require(newLimit > 0, "RateLimiter: zero limit");
        require(newLimit <= dailyMintLimit, "RateLimiter: exceeds daily limit");
        perAddressDailyLimit = newLimit;
        emit PerAddressLimitUpdated(newLimit);
    }

    function getRemainingGlobalLimit() external view returns (uint256) {
        uint256 effectiveMinted = currentDayMinted;
        if (block.timestamp >= lastResetTimestamp + 1 days) {
            effectiveMinted = 0;
        }
        return dailyMintLimit > effectiveMinted ? dailyMintLimit - effectiveMinted : 0;
    }

    function getRemainingAddressLimit(address user) external view returns (uint256) {
        uint256 effectiveMinted = addressDailyMinted[user];
        if (block.timestamp >= addressLastReset[user] + 1 days) {
            effectiveMinted = 0;
        }
        return perAddressDailyLimit > effectiveMinted ? perAddressDailyLimit - effectiveMinted : 0;
    }
}

contracts-axusd/stablecoin/core/ReserveM.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "../interfaces/IBackstopVault.sol";
import "../interfaces/ITBillVault.sol";

interface IPSMReserve {
    function collateral() external view returns (address);
    function debtOutstanding() external view returns (uint256);
}

contract ReserveManager is AccessControl, ReentrancyGuard, Pausable {
    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");
    bytes32 public constant GUARDIAN_ROLE = keccak256("GUARDIAN_ROLE");
    bytes32 public constant REBALANCER_ROLE = keccak256("REBALANCER_ROLE");

    IBackstopVault public backstopVault;
    ITBillVault public tbillVault;
    address public vaultEngine;

    address public psm;
    uint8 public psmCollateralDecimals;

    uint256 public targetTBillRatio;
    uint256 public targetBackstopRatio;
    uint256 public rebalanceThreshold;

    uint256 public constant BASIS_POINTS = 10000;

    struct ReserveStatus {
        uint256 totalReserves;
        uint256 tbillValue;
        uint256 backstopValue;
        uint256 vaultCollateral;
        uint256 currentTBillRatio;
        uint256 currentBackstopRatio;
        bool needsRebalance;
    }

    event RebalanceExecuted(uint256 tbillDelta, uint256 backstopDelta);
    event TargetRatiosUpdated(uint256 tbillRatio, uint256 backstopRatio);
    event RebalanceThresholdUpdated(uint256 newThreshold);
    event BackstopVaultUpdated(address indexed oldVault, address indexed newVault);
    event TBillVaultUpdated(address indexed oldVault, address indexed newVault);
    event PSMUpdated(address indexed newPsm, uint8 decimals);

    constructor(
        address _backstopVault,
        address _tbillVault,
        address _vaultEngine,
        uint256 _targetTBillRatio,
        uint256 _targetBackstopRatio
    ) {
        require(_targetTBillRatio + _targetBackstopRatio <= BASIS_POINTS, "ReserveManager: ratios exceed 100%");

        backstopVault = IBackstopVault(_backstopVault);
        tbillVault = ITBillVault(_tbillVault);
        vaultEngine = _vaultEngine;

        targetTBillRatio = _targetTBillRatio;
        targetBackstopRatio = _targetBackstopRatio;
        rebalanceThreshold = 500;

        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(ADMIN_ROLE, msg.sender);
        _grantRole(GUARDIAN_ROLE, msg.sender);
    }

    function setPSM(address _psm, uint8 _decimals) external onlyRole(ADMIN_ROLE) {
        psm = _psm;
        psmCollateralDecimals = _decimals;
        emit PSMUpdated(_psm, _decimals);
    }

    function _getPSMReserves() internal view returns (uint256) {
        if (psm == address(0)) return 0;

        address collateralToken = IPSMReserve(psm).collateral();
        uint256 balance = IERC20(collateralToken).balanceOf(psm);

        if (psmCollateralDecimals < 18) {
            return balance * (10 ** (18 - psmCollateralDecimals));
        } else if (psmCollateralDecimals > 18) {
            return balance / (10 ** (psmCollateralDecimals - 18));
        }
        return balance;
    }

    function getReserveStatus() external view returns (ReserveStatus memory) {
        uint256 tbillValue = tbillVault.getTotalValue();
        uint256 backstopValue = backstopVault.getBalance();
        uint256 psmValue = _getPSMReserves();

        uint256 totalReserves = tbillValue + backstopValue + psmValue;

        uint256 currentTBillRatio = 0;
        uint256 currentBackstopRatio = 0;

        if (totalReserves > 0) {
            currentTBillRatio = (tbillValue * BASIS_POINTS) / totalReserves;
            currentBackstopRatio = (backstopValue * BASIS_POINTS) / totalReserves;
        }

        bool needsRebalance = false;
        if (currentTBillRatio > targetTBillRatio + rebalanceThreshold ||
            currentTBillRatio < targetTBillRatio - rebalanceThreshold ||
            currentBackstopRatio > targetBackstopRatio + rebalanceThreshold ||
            currentBackstopRatio < targetBackstopRatio - rebalanceThreshold) {
            needsRebalance = true;
        }

        return ReserveStatus({
            totalReserves: totalReserves,
            tbillValue: tbillValue,
            backstopValue: backstopValue,
            vaultCollateral: 0,
            currentTBillRatio: currentTBillRatio,
            currentBackstopRatio: currentBackstopRatio,
            needsRebalance: needsRebalance
        });
    }

    function getHealthFactor() external view returns (uint256) {
        uint256 tbillValue = tbillVault.getTotalValue();
        uint256 backstopValue = backstopVault.getBalance();
        uint256 psmValue = _getPSMReserves();
        uint256 totalReserves = tbillValue + backstopValue + psmValue;

        if (totalReserves == 0) return 0;

        uint256 tbillHealth = (tbillValue * BASIS_POINTS) / totalReserves;
        uint256 backstopHealth = (backstopValue * BASIS_POINTS) / totalReserves;

        uint256 tbillDeviation = tbillHealth > targetTBillRatio 
            ? tbillHealth - targetTBillRatio 
            : targetTBillRatio - tbillHealth;

        uint256 backstopDeviation = backstopHealth > targetBackstopRatio 
            ? backstopHealth - targetBackstopRatio 
            : targetBackstopRatio - backstopHealth;

        uint256 totalDeviation = tbillDeviation + backstopDeviation;

        if (totalDeviation >= BASIS_POINTS) return 0;
        return BASIS_POINTS - totalDeviation;
    }

    function setTargetRatios(uint256 _tbillRatio, uint256 _backstopRatio) external onlyRole(ADMIN_ROLE) {
        require(_tbillRatio + _backstopRatio <= BASIS_POINTS, "ReserveManager: ratios exceed 100%");
        targetTBillRatio = _tbillRatio;
        targetBackstopRatio = _backstopRatio;
        emit TargetRatiosUpdated(_tbillRatio, _backstopRatio);
    }

    function setRebalanceThreshold(uint256 _threshold) external onlyRole(ADMIN_ROLE) {
        require(_threshold <= 2000, "ReserveManager: threshold too high");
        rebalanceThreshold = _threshold;
        emit RebalanceThresholdUpdated(_threshold);
    }

    function setBackstopVault(address _vault) external onlyRole(ADMIN_ROLE) {
        require(_vault != address(0), "ReserveManager: zero address");
        address oldVault = address(backstopVault);
        backstopVault = IBackstopVault(_vault);
        emit BackstopVaultUpdated(oldVault, _vault);
    }

    function setTBillVault(address _vault) external onlyRole(ADMIN_ROLE) {
        require(_vault != address(0), "ReserveManager: zero address");
        address oldVault = address(tbillVault);
        tbillVault = ITBillVault(_vault);
        emit TBillVaultUpdated(oldVault, _vault);
    }

    function pause() external onlyRole(GUARDIAN_ROLE) {
        _pause();
    }

    function unpause() external onlyRole(ADMIN_ROLE) {
        _unpause();
    }
}

