// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

/**
 * @title SegregatedCustody
 * @notice GENIUS Act compliant custody contract for AXUSD reserve assets
 * @dev Implements:
 *   - Segregated custody: Reserve assets held separately from operational funds
 *   - Anti-rehypothecation: Assets cannot be pledged, lent, or reused
 *   - Audit trail: Complete history of all custody movements
 *   - Insolvency priority: Assets protected for stablecoin holder claims
 */
contract SegregatedCustody is AccessControl, ReentrancyGuard, Pausable {
    using SafeERC20 for IERC20;

    bytes32 public constant CUSTODIAN_ROLE = keccak256("CUSTODIAN_ROLE");
    bytes32 public constant AUDITOR_ROLE = keccak256("AUDITOR_ROLE");
    bytes32 public constant REDEMPTION_ROLE = keccak256("REDEMPTION_ROLE");

    struct CustodyRecord {
        address asset;
        uint256 amount;
        uint256 timestamp;
        string purpose;
        address depositor;
    }

    struct RedemptionRecord {
        address asset;
        uint256 amount;
        uint256 timestamp;
        address recipient;
        string reason;
    }

    mapping(address => uint256) public assetBalances;
    address[] public custodiedAssets;
    mapping(address => bool) public isCustodiedAsset;

    CustodyRecord[] public depositHistory;
    RedemptionRecord[] public redemptionHistory;

    bool public rehypothecationBlocked;
    bool public insolvencyProtectionActive;

    address public stablecoinContract;
    uint256 public totalStablecoinSupply;

    mapping(address => bool) public approvedDestinations;

    event AssetDeposited(
        address indexed asset,
        uint256 amount,
        address indexed depositor,
        string purpose,
        uint256 indexed recordId
    );

    event AssetRedeemed(
        address indexed asset,
        uint256 amount,
        address indexed recipient,
        string reason,
        uint256 indexed recordId
    );

    event RehypothecationStatusChanged(bool blocked);
    event InsolvencyProtectionChanged(bool active);
    event ApprovedDestinationAdded(address indexed destination);
    event ApprovedDestinationRemoved(address indexed destination);
    event StablecoinSupplyUpdated(uint256 newSupply);

    error RehypothecationBlocked();
    error InsufficientReserves();
    error UnauthorizedDestination();
    error InsolvencyProtectionActive();

    constructor(address _stablecoinContract, address _psmContract) {
        stablecoinContract = _stablecoinContract;
        rehypothecationBlocked = true;
        insolvencyProtectionActive = true;

        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(CUSTODIAN_ROLE, msg.sender);
        _grantRole(AUDITOR_ROLE, msg.sender);

        if (_psmContract != address(0)) {
            _grantRole(REDEMPTION_ROLE, _psmContract);
            approvedDestinations[_psmContract] = true;
        }
    }

    function grantRedemptionRole(address account) external onlyRole(DEFAULT_ADMIN_ROLE) {
        _grantRole(REDEMPTION_ROLE, account);
        approvedDestinations[account] = true;
    }

    function depositAsset(
        address asset,
        uint256 amount,
        string calldata purpose
    ) external nonReentrant whenNotPaused onlyRole(CUSTODIAN_ROLE) {
        require(asset != address(0), "SegregatedCustody: zero asset");
        require(amount > 0, "SegregatedCustody: zero amount");

        IERC20(asset).safeTransferFrom(msg.sender, address(this), amount);

        if (!isCustodiedAsset[asset]) {
            custodiedAssets.push(asset);
            isCustodiedAsset[asset] = true;
        }

        assetBalances[asset] += amount;

        depositHistory.push(CustodyRecord({
            asset: asset,
            amount: amount,
            timestamp: block.timestamp,
            purpose: purpose,
            depositor: msg.sender
        }));

        emit AssetDeposited(asset, amount, msg.sender, purpose, depositHistory.length - 1);
    }

    function redeemForStablecoinHolder(
        address asset,
        uint256 amount,
        address recipient,
        string calldata reason
    ) external nonReentrant whenNotPaused onlyRole(REDEMPTION_ROLE) {
        require(asset != address(0), "SegregatedCustody: zero asset");
        require(amount > 0, "SegregatedCustody: zero amount");
        require(recipient != address(0), "SegregatedCustody: zero recipient");
        require(assetBalances[asset] >= amount, "SegregatedCustody: insufficient balance");

        if (!approvedDestinations[recipient] && insolvencyProtectionActive) {
            revert UnauthorizedDestination();
        }

        assetBalances[asset] -= amount;

        IERC20(asset).safeTransfer(recipient, amount);

        redemptionHistory.push(RedemptionRecord({
            asset: asset,
            amount: amount,
            timestamp: block.timestamp,
            recipient: recipient,
            reason: reason
        }));

        emit AssetRedeemed(asset, amount, recipient, reason, redemptionHistory.length - 1);
    }

    function transferToAnotherVault(
        address asset,
        uint256 amount,
        address destination
    ) external nonReentrant onlyRole(CUSTODIAN_ROLE) {
        if (rehypothecationBlocked) {
            revert RehypothecationBlocked();
        }

        require(approvedDestinations[destination], "SegregatedCustody: unapproved destination");
        require(assetBalances[asset] >= amount, "SegregatedCustody: insufficient balance");

        assetBalances[asset] -= amount;
        IERC20(asset).safeTransfer(destination, amount);
    }

    function addApprovedDestination(address destination) external onlyRole(DEFAULT_ADMIN_ROLE) {
        approvedDestinations[destination] = true;
        emit ApprovedDestinationAdded(destination);
    }

    function removeApprovedDestination(address destination) external onlyRole(DEFAULT_ADMIN_ROLE) {
        approvedDestinations[destination] = false;
        emit ApprovedDestinationRemoved(destination);
    }

    function setRehypothecationBlocked(bool blocked) external onlyRole(DEFAULT_ADMIN_ROLE) {
        rehypothecationBlocked = blocked;
        emit RehypothecationStatusChanged(blocked);
    }

    function setInsolvencyProtection(bool active) external onlyRole(DEFAULT_ADMIN_ROLE) {
        insolvencyProtectionActive = active;
        emit InsolvencyProtectionChanged(active);
    }

    function updateStablecoinSupply(uint256 supply) external onlyRole(AUDITOR_ROLE) {
        totalStablecoinSupply = supply;
        emit StablecoinSupplyUpdated(supply);
    }

    function getTotalReserveValue() external view returns (uint256) {
        uint256 total = 0;
        for (uint256 i = 0; i < custodiedAssets.length; i++) {
            total += assetBalances[custodiedAssets[i]];
        }
        return total;
    }

    function getReserveRatio() external view returns (uint256) {
        if (totalStablecoinSupply == 0) return 0;

        uint256 totalReserves = 0;
        for (uint256 i = 0; i < custodiedAssets.length; i++) {
            totalReserves += assetBalances[custodiedAssets[i]];
        }

        return (totalReserves * 10000) / totalStablecoinSupply;
    }

    function getDepositCount() external view returns (uint256) {
        return depositHistory.length;
    }

    function getRedemptionCount() external view returns (uint256) {
        return redemptionHistory.length;
    }

    function getCustodiedAssets() external view returns (address[] memory) {
        return custodiedAssets;
    }

    function getComplianceStatus() external view returns (
        bool segregated,
        bool antiRehypothecation,
        bool insolvencyProtection,
        uint256 reserveRatio
    ) {
        segregated = true;
        antiRehypothecation = rehypothecationBlocked;
        insolvencyProtection = insolvencyProtectionActive;

        if (totalStablecoinSupply > 0) {
            uint256 totalReserves = 0;
            for (uint256 i = 0; i < custodiedAssets.length; i++) {
                totalReserves += assetBalances[custodiedAssets[i]];
            }
            reserveRatio = (totalReserves * 10000) / totalStablecoinSupply;
        }
    }

    function pause() external onlyRole(DEFAULT_ADMIN_ROLE) {
        _pause();
    }

    function unpause() external onlyRole(DEFAULT_ADMIN_ROLE) {
        _unpause();
    }
}

contracts-axusd/stablecoin/core/TBillVau.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "../interfaces/IAxiomStable.sol";
import "../interfaces/ITBillVault.sol";

interface ITBillToken {
    function decimals() external view returns (uint8);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
}

interface IYieldSource {
    function claimYield(address token) external returns (uint256);
    function pendingYield(address token) external view returns (uint256);
}

interface IGeniusComplianceTBill {
    function isYieldBlocked() external view returns (bool);
}

contract TBillVault is AccessControl, ReentrancyGuard, Pausable, ITBillVault {
    using SafeERC20 for IERC20;

    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");
    bytes32 public constant GUARDIAN_ROLE = keccak256("GUARDIAN_ROLE");
    bytes32 public constant YIELD_MANAGER_ROLE = keccak256("YIELD_MANAGER_ROLE");

    IAxiomStable public immutable axusd;

    mapping(address => TBillAsset) public tbillAssets;
    address[] public supportedTokens;

    mapping(address => uint8) public tokenDecimals;
    mapping(address => uint256) public lastYieldTimestamp;
    mapping(address => uint256) public accumulatedYield;

    address public feeBurner;
    address public insuranceFund;
    uint256 public feeBurnerShare;
    uint256 public insuranceShare;

    uint256 public constant BASIS_POINTS = 10000;
    uint256 public constant PRECISION = 1e18;

    uint256 public totalMintedAgainstTBills;
    uint256 public maxMintRatio;

    IYieldSource public yieldSource;

    IGeniusComplianceTBill public geniusCompliance;
    bool public geniusComplianceEnabled;

    bool public maturityEnforcementEnabled;
    uint256 public maxMaturityDays;
    uint256 public constant GENIUS_ACT_MAX_MATURITY = 93 days;

    bool public holderYieldDistributionBlocked;

    event MaxMintRatioUpdated(uint256 newRatio);
    event FeeBurnerUpdated(address indexed newFeeBurner);
    event InsuranceFundUpdated(address indexed newFund);
    event SharesUpdated(uint256 feeBurnerShare, uint256 insuranceShare);
    event YieldSourceUpdated(address indexed newSource);
    event GeniusComplianceUpdated(address indexed compliance, bool enabled);

    constructor(
        address _axusd,
        address _feeBurner,
        address _insuranceFund,
        uint256 _maxMintRatio
    ) {
        require(_axusd != address(0), "TBillVault: zero axusd");
        require(_maxMintRatio >= 5000 && _maxMintRatio <= 10000, "TBillVault: invalid ratio");

        axusd = IAxiomStable(_axusd);
        feeBurner = _feeBurner;
        insuranceFund = _insuranceFund;
        maxMintRatio = _maxMintRatio;

        feeBurnerShare = 5000;
        insuranceShare = 2500;

        maturityEnforcementEnabled = true;
        maxMaturityDays = GENIUS_ACT_MAX_MATURITY;
        holderYieldDistributionBlocked = true;

        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(ADMIN_ROLE, msg.sender);
        _grantRole(GUARDIAN_ROLE, msg.sender);
        _grantRole(YIELD_MANAGER_ROLE, msg.sender);
    }

    function setMaturityEnforcement(bool _enabled, uint256 _maxDays) external onlyRole(ADMIN_ROLE) {
        maturityEnforcementEnabled = _enabled;
        maxMaturityDays = _maxDays > 0 ? _maxDays : GENIUS_ACT_MAX_MATURITY;
        emit MaturityEnforcementUpdated(_enabled, maxMaturityDays);
    }

    function addTBillAsset(
        address token,
        string calldata name,
        uint256 expectedYieldRate,
        uint256 maturityDate
    ) external onlyRole(ADMIN_ROLE) {
        require(token != address(0), "TBillVault: zero token");
        require(tbillAssets[token].token == address(0), "TBillVault: already added");

        if (maturityEnforcementEnabled) {
            require(maturityDate > block.timestamp, "TBillVault: maturity must be in future");
            require(maturityDate <= block.timestamp + maxMaturityDays, "TBillVault: maturity exceeds GENIUS Act limit");
        }

        uint8 decimals = ITBillToken(token).decimals();
        tokenDecimals[token] = decimals;

        tbillAssets[token] = TBillAsset({
            token: token,
            name: name,
            balance: 0,
            yieldRate: expectedYieldRate,
            maturityDate: maturityDate,
            enabled: true
        });

        supportedTokens.push(token);
        lastYieldTimestamp[token] = block.timestamp;

        emit TBillAssetAdded(token, name, maturityDate);
    }

    function removeTBillAsset(address token) external onlyRole(ADMIN_ROLE) {
        require(tbillAssets[token].token != address(0), "TBillVault: not added");
        require(tbillAssets[token].balance == 0, "TBillVault: has balance");

        tbillAssets[token].enabled = false;
        emit TBillAssetRemoved(token);
    }

    function depositTBill(address token, uint256 amount) external override nonReentrant whenNotPaused onlyRole(ADMIN_ROLE) {
        require(amount > 0, "TBillVault: zero amount");
        TBillAsset storage asset = tbillAssets[token];
        require(asset.token != address(0), "TBillVault: unsupported token");
        require(asset.enabled, "TBillVault: token disabled");

        if (maturityEnforcementEnabled && asset.maturityDate > 0) {
            require(asset.maturityDate > block.timestamp, "TBillVault: asset has matured");
        }

        IERC20(token).safeTransferFrom(msg.sender, address(this), amount);

        asset.balance += amount;

        uint256 axusdValue = _toAxusdDecimals(token, amount);
        uint256 maxMintable = (axusdValue * maxMintRatio) / BASIS_POINTS;

        if (maxMintable > 0) {
            totalMintedAgainstTBills += maxMintable;
            axusd.mint(address(this), maxMintable);
        }

        emit TBillDeposited(token, amount, maxMintable);
    }

    function withdrawTBill(address token, uint256 amount) external override nonReentrant onlyRole(ADMIN_ROLE) {
        require(amount > 0, "TBillVault: zero amount");
        TBillAsset storage asset = tbillAssets[token];
        require(asset.token != address(0), "TBillVault: unsupported token");
        require(asset.balance >= amount, "TBillVault: insufficient balance");

        uint256 axusdValue = _toAxusdDecimals(token, amount);
        uint256 axusdToburn = (axusdValue * maxMintRatio) / BASIS_POINTS;

        if (axusdToburn > 0 && totalMintedAgainstTBills >= axusdToburn) {
            totalMintedAgainstTBills -= axusdToburn;
            axusd.burn(address(this), axusdToburn);
        }

        asset.balance -= amount;
        IERC20(token).safeTransfer(msg.sender, amount);

        emit TBillWithdrawn(token, amount);
    }

    function harvestYield(address token) external override nonReentrant onlyRole(YIELD_MANAGER_ROLE) returns (uint256) {
        TBillAsset storage asset = tbillAssets[token];
        require(asset.token != address(0), "TBillVault: unsupported token");

        uint256 yieldAmount = 0;

        if (address(yieldSource) != address(0)) {
            yieldAmount = yieldSource.claimYield(token);
        } else {
            uint256 timeElapsed = block.timestamp - lastYieldTimestamp[token];
            yieldAmount = (asset.balance * asset.yieldRate * timeElapsed) / (BASIS_POINTS * 365 days);
        }

        if (yieldAmount > 0) {
            accumulatedYield[token] += yieldAmount;
            lastYieldTimestamp[token] = block.timestamp;
            emit YieldHarvested(token, yieldAmount);
        }

        return yieldAmount;
    }

    function harvestAllYields() external override nonReentrant onlyRole(YIELD_MANAGER_ROLE) returns (uint256) {
        uint256 totalYield = 0;

        for (uint256 i = 0; i < supportedTokens.length; i++) {
            address token = supportedTokens[i];
            if (tbillAssets[token].enabled && tbillAssets[token].balance > 0) {
                uint256 yieldAmount = 0;

                if (address(yieldSource) != address(0)) {
                    yieldAmount = yieldSource.claimYield(token);
                } else {
                    uint256 timeElapsed = block.timestamp - lastYieldTimestamp[token];
                    yieldAmount = (tbillAssets[token].balance * tbillAssets[token].yieldRate * timeElapsed) / (BASIS_POINTS * 365 days);
                }

                if (yieldAmount > 0) {
                    accumulatedYield[token] += yieldAmount;
                    lastYieldTimestamp[token] = block.timestamp;
                    totalYield += _toAxusdDecimals(token, yieldAmount);
                    emit YieldHarvested(token, yieldAmount);
                }
            }
        }

        return totalYield;
    }

    function setGeniusCompliance(address _compliance, bool _enabled) external onlyRole(ADMIN_ROLE) {
        geniusCompliance = IGeniusComplianceTBill(_compliance);
        geniusComplianceEnabled = _enabled;
        emit GeniusComplianceUpdated(_compliance, _enabled);
    }

    function distributeYield() external nonReentrant onlyRole(YIELD_MANAGER_ROLE) {
        require(!holderYieldDistributionBlocked, "TBillVault: yield to holders blocked by GENIUS Act");

        if (geniusComplianceEnabled && address(geniusCompliance) != address(0)) {
            require(!geniusCompliance.isYieldBlocked(), "TBillVault: yield distribution blocked by GENIUS Act");
        }

        uint256 totalYieldValue = 0;

        for (uint256 i = 0; i < supportedTokens.length; i++) {
            address token = supportedTokens[i];
            if (accumulatedYield[token] > 0) {
                totalYieldValue += _toAxusdDecimals(token, accumulatedYield[token]);
                accumulatedYield[token] = 0;
            }
        }

        require(totalYieldValue > 0, "TBillVault: no yield to distribute");

        uint256 toFeeBurner = (totalYieldValue * feeBurnerShare) / BASIS_POINTS;
        uint256 toInsurance = (totalYieldValue * insuranceShare) / BASIS_POINTS;
        uint256 toReserves = totalYieldValue - toFeeBurner - toInsurance;

        if (toFeeBurner > 0 && feeBurner != address(0)) {
            axusd.mint(feeBurner, toFeeBurner);
        }

        if (toInsurance > 0 && insuranceFund != address(0)) {
            axusd.mint(insuranceFund, toInsurance);
        }

        if (toReserves > 0) {
            totalMintedAgainstTBills += toReserves;
        }

        emit YieldDistributed(totalYieldValue, toFeeBurner, toInsurance);
    }

    function _toAxusdDecimals(address token, uint256 amount) internal view returns (uint256) {
        uint8 decimals = tokenDecimals[token];
        if (decimals < 18) {
            return amount * (10 ** (18 - decimals));
        } else if (decimals > 18) {
            return amount / (10 ** (decimals - 18));
        }
        return amount;
    }

    function getTotalValue() external view override returns (uint256) {
        uint256 total = 0;
        for (uint256 i = 0; i < supportedTokens.length; i++) {
            address token = supportedTokens[i];
            if (tbillAssets[token].balance > 0) {
                total += _toAxusdDecimals(token, tbillAssets[token].balance);
            }
        }
        return total;
    }

    function getAssetValue(address token) external view override returns (uint256) {
        return _toAxusdDecimals(token, tbillAssets[token].balance);
    }

    function getSupportedAssets() external view override returns (address[] memory) {
        return supportedTokens;
    }

    function getPendingYield(address token) external view returns (uint256) {
        if (address(yieldSource) != address(0)) {
            return yieldSource.pendingYield(token);
        }
        TBillAsset memory asset = tbillAssets[token];
        uint256 timeElapsed = block.timestamp - lastYieldTimestamp[token];
        return (asset.balance * asset.yieldRate * timeElapsed) / (BASIS_POINTS * 365 days);
    }

    function setMaxMintRatio(uint256 _ratio) external onlyRole(ADMIN_ROLE) {
        require(_ratio >= 5000 && _ratio <= 10000, "TBillVault: invalid ratio");
        maxMintRatio = _ratio;
        emit MaxMintRatioUpdated(_ratio);
    }

    function setFeeBurner(address _feeBurner) external onlyRole(ADMIN_ROLE) {
        feeBurner = _feeBurner;
        emit FeeBurnerUpdated(_feeBurner);
    }

    function setInsuranceFund(address _fund) external onlyRole(ADMIN_ROLE) {
        insuranceFund = _fund;
        emit InsuranceFundUpdated(_fund);
    }

    function setShares(uint256 _feeBurnerShare, uint256 _insuranceShare) external onlyRole(ADMIN_ROLE) {
        require(_feeBurnerShare + _insuranceShare <= BASIS_POINTS, "TBillVault: shares exceed 100%");
        feeBurnerShare = _feeBurnerShare;
        insuranceShare = _insuranceShare;
        emit SharesUpdated(_feeBurnerShare, _insuranceShare);
    }

    function setYieldSource(address _source) external onlyRole(ADMIN_ROLE) {
        yieldSource = IYieldSource(_source);
        emit YieldSourceUpdated(_source);
    }

    function pause() external onlyRole(GUARDIAN_ROLE) {
        _pause();
    }

    function unpause() external onlyRole(ADMIN_ROLE) {
        _unpause();
    }
}

contracts-axusd/stablecoin/core/VaultEng.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "../interfaces/IAxiomStable.sol";
import "../interfaces/IOracleAdapter.sol";
import "../interfaces/IRateLimiter.sol";
import "../interfaces/IVaultEngine.sol";
import "../lib/VaultMath.sol";

interface IGeniusCompliance {
    function isApprovedCollateral(address token) external view returns (bool);
    function isYieldBlocked() external view returns (bool);
}

interface IReserveManager {
    function getReserveStatus() external view returns (
        uint256 totalReserves,
        uint256 tbillValue,
        uint256 backstopValue,
        uint256 vaultCollateral,
        uint256 currentTBillRatio,
        uint256 currentBackstopRatio,
        bool needsRebalance
    );
}

contract VaultEngine is AccessControl, Pausable, ReentrancyGuard, IVaultEngine {
    using SafeERC20 for IERC20;
    using VaultMath for uint256;

    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");
    bytes32 public constant GUARDIAN_ROLE = keccak256("GUARDIAN_ROLE");
    bytes32 public constant LIQUIDATOR_ROLE = keccak256("LIQUIDATOR_ROLE");

    IAxiomStable public immutable axusd;
    IOracleAdapter public oracleAdapter;
    IRateLimiter public rateLimiter;
    address public feeBurner;

    IGeniusCompliance public geniusCompliance;
    bool public geniusComplianceEnabled;

    IReserveManager public reserveManager;
    bool public reserveBackingEnforced;

    uint256 public globalDebtCeiling;
    uint256 public totalGlobalDebt;
    uint256 public accruedFees;

    mapping(address => CollateralConfig) public collateralConfigs;
    mapping(address => mapping(address => Vault)) public vaults;
    address[] public collateralList;

    uint256 public constant BASIS_POINTS = 10000;
    uint256 public constant PRECISION = 1e18;

    event CollateralAdded(address indexed collateral, uint256 minRatio, uint256 liquidationThreshold, uint256 fee);
    event CollateralUpdated(address indexed collateral);
    event CollateralDisabled(address indexed collateral);
    event GlobalDebtCeilingUpdated(uint256 newCeiling);
    event FeesRouted(address indexed feeBurner, uint256 amount);
    event OracleAdapterUpdated(address indexed newAdapter);
    event RateLimiterUpdated(address indexed newLimiter);
    event FeeBurnerUpdated(address indexed newFeeBurner);
    event GeniusComplianceUpdated(address indexed compliance, bool enabled);
    event ReserveManagerUpdated(address indexed manager, bool backingEnforced);

    constructor(
        address _axusd,
        address _oracleAdapter,
        address _rateLimiter,
        uint256 _globalDebtCeiling
    ) {
        require(_axusd != address(0), "VaultEngine: zero axusd");
        require(_oracleAdapter != address(0), "VaultEngine: zero oracle");
        require(_rateLimiter != address(0), "VaultEngine: zero limiter");

        axusd = IAxiomStable(_axusd);
        oracleAdapter = IOracleAdapter(_oracleAdapter);
        rateLimiter = IRateLimiter(_rateLimiter);
        globalDebtCeiling = _globalDebtCeiling;

        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(ADMIN_ROLE, msg.sender);
        _grantRole(GUARDIAN_ROLE, msg.sender);
    }

    function setGeniusCompliance(address _compliance, bool _enabled) external onlyRole(ADMIN_ROLE) {
        geniusCompliance = IGeniusCompliance(_compliance);
        geniusComplianceEnabled = _enabled;
        emit GeniusComplianceUpdated(_compliance, _enabled);
    }

    function setReserveManager(address _manager, bool _enforced) external onlyRole(ADMIN_ROLE) {
        reserveManager = IReserveManager(_manager);
        reserveBackingEnforced = _enforced;
        emit ReserveManagerUpdated(_manager, _enforced);
    }

    function _checkReserveBacking(uint256 additionalDebt) internal view {
        if (!reserveBackingEnforced || address(reserveManager) == address(0)) return;

        (uint256 totalReserves,,,,,, ) = reserveManager.getReserveStatus();
        uint256 projectedSupply = totalGlobalDebt + additionalDebt;

        require(totalReserves >= projectedSupply, "VaultEngine: insufficient reserves for 100% backing");
    }

    function addCollateral(
        address collateral,
        uint256 minCollateralRatio,
        uint256 liquidationThreshold,
        uint256 liquidationPenalty,
        uint256 debtCeiling,
        uint256 stabilityFee
    ) external onlyRole(ADMIN_ROLE) {
        require(collateral != address(0), "VaultEngine: zero collateral");
        require(collateralConfigs[collateral].minCollateralRatio == 0, "VaultEngine: already added");
        require(minCollateralRatio >= 11000, "VaultEngine: ratio too low");
        require(liquidationThreshold < minCollateralRatio, "VaultEngine: invalid threshold");
        require(liquidationThreshold >= 10000, "VaultEngine: threshold below 100%");
        require(liquidationPenalty <= 2000, "VaultEngine: penalty too high");
        require(stabilityFee <= 2000, "VaultEngine: fee too high");
        require(oracleAdapter.isFeedValid(collateral), "VaultEngine: no valid feed");

        if (geniusComplianceEnabled && address(geniusCompliance) != address(0)) {
            require(geniusCompliance.isApprovedCollateral(collateral), "VaultEngine: collateral not GENIUS compliant");
        }

        collateralConfigs[collateral] = CollateralConfig({
            priceFeed: address(0),
            minCollateralRatio: minCollateralRatio,
            liquidationThreshold: liquidationThreshold,
            liquidationPenalty: liquidationPenalty,
            debtCeiling: debtCeiling,
            stabilityFee: stabilityFee,
            totalDebt: 0,
            enabled: true
        });

        collateralList.push(collateral);
        emit CollateralAdded(collateral, minCollateralRatio, liquidationThreshold, stabilityFee);
    }

    function disableCollateral(address collateral) external onlyRole(GUARDIAN_ROLE) {
        require(collateralConfigs[collateral].minCollateralRatio > 0, "VaultEngine: not added");
        collateralConfigs[collateral].enabled = false;
        emit CollateralDisabled(collateral);
    }

    function disableNonCompliantCollateral() external onlyRole(ADMIN_ROLE) {
        require(geniusComplianceEnabled && address(geniusCompliance) != address(0), "VaultEngine: compliance not enabled");

        for (uint256 i = 0; i < collateralList.length; i++) {
            address collateral = collateralList[i];
            if (collateralConfigs[collateral].enabled && !geniusCompliance.isApprovedCollateral(collateral)) {
                collateralConfigs[collateral].enabled = false;
                emit CollateralDisabled(collateral);
            }
        }
    }

    function getCollateralList() external view returns (address[] memory) {
        return collateralList;
    }

    function depositCollateral(address collateral, uint256 amount) external override nonReentrant whenNotPaused {
        require(amount > 0, "VaultEngine: zero amount");
        CollateralConfig storage config = collateralConfigs[collateral];
        require(config.minCollateralRatio > 0, "VaultEngine: unsupported collateral");
        require(config.enabled, "VaultEngine: collateral disabled");

        if (geniusComplianceEnabled && address(geniusCompliance) != address(0)) {
            require(geniusCompliance.isApprovedCollateral(collateral), "VaultEngine: collateral not GENIUS compliant");
        }

        IERC20(collateral).safeTransferFrom(msg.sender, address(this), amount);

        Vault storage vault = vaults[msg.sender][collateral];
        vault.collateralAmount += amount;

        if (vault.lastAccrualTimestamp == 0) {
            vault.lastAccrualTimestamp = block.timestamp;
        }

        emit CollateralDeposited(msg.sender, collateral, amount);
    }

    function withdrawCollateral(address collateral, uint256 amount) external override nonReentrant whenNotPaused {
        require(amount > 0, "VaultEngine: zero amount");

        Vault storage vault = vaults[msg.sender][collateral];
        require(vault.collateralAmount >= amount, "VaultEngine: insufficient collateral");

        _accrueInterest(msg.sender, collateral);

        uint256 newCollateralAmount = vault.collateralAmount - amount;

        if (vault.debtAmount > 0) {
            uint256 collateralPrice = oracleAdapter.getPrice(collateral);
            uint256 newCollateralValue = (newCollateralAmount * collateralPrice) / PRECISION;
            uint256 newRatio = VaultMath.calculateCollateralRatio(newCollateralValue, vault.debtAmount);
            require(newRatio >= collateralConfigs[collateral].minCollateralRatio, "VaultEngine: below min ratio");
        }

        vault.collateralAmount = newCollateralAmount;
        IERC20(collateral).safeTransfer(msg.sender, amount);

        emit CollateralWithdrawn(msg.sender, collateral, amount);
    }

    function mintAXUSD(address collateral, uint256 amount) external override nonReentrant whenNotPaused {
        require(amount > 0, "VaultEngine: zero amount");

        CollateralConfig storage config = collateralConfigs[collateral];
        require(config.minCollateralRatio > 0, "VaultEngine: unsupported collateral");
        require(config.enabled, "VaultEngine: collateral disabled");

        if (geniusComplianceEnabled && address(geniusCompliance) != address(0)) {
            require(geniusCompliance.isApprovedCollateral(collateral), "VaultEngine: collateral not GENIUS compliant");
        }

        Vault storage vault = vaults[msg.sender][collateral];
        require(vault.collateralAmount > 0, "VaultEngine: no collateral");

        _accrueInterest(msg.sender, collateral);

        _checkReserveBacking(amount);

        require(totalGlobalDebt + amount <= globalDebtCeiling, "VaultEngine: global ceiling");
        require(config.totalDebt + amount <= config.debtCeiling, "VaultEngine: collateral ceiling");
        require(rateLimiter.checkMintLimit(msg.sender, amount), "VaultEngine: rate limit");

        uint256 collateralPrice = oracleAdapter.getPrice(collateral);
        uint256 collateralValue = (vault.collateralAmount * collateralPrice) / PRECISION;
        uint256 newDebt = vault.debtAmount + amount;
        uint256 newRatio = VaultMath.calculateCollateralRatio(collateralValue, newDebt);
        require(newRatio >= config.minCollateralRatio, "VaultEngine: below min ratio");

        vault.debtAmount = newDebt;
        config.totalDebt += amount;
        totalGlobalDebt += amount;

        rateLimiter.recordMint(msg.sender, amount);
        axusd.mint(msg.sender, amount);

        emit AXUSDMinted(msg.sender, collateral, amount);
    }

    function repayAXUSD(address collateral, uint256 amount) external override nonReentrant whenNotPaused {
        require(amount > 0, "VaultEngine: zero amount");

        Vault storage vault = vaults[msg.sender][collateral];
        require(vault.debtAmount > 0, "VaultEngine: no debt");

        _accrueInterest(msg.sender, collateral);

        uint256 repayAmount = VaultMath.min(amount, vault.debtAmount);

        vault.debtAmount -= repayAmount;
        collateralConfigs[collateral].totalDebt -= repayAmount;
        totalGlobalDebt -= repayAmount;

        axusd.burn(msg.sender, repayAmount);

        emit AXUSDRepaid(msg.sender, collateral, repayAmount);
    }

    function _accrueInterest(address user, address collateral) internal {
        Vault storage vault = vaults[user][collateral];
        if (vault.debtAmount == 0 || vault.lastAccrualTimestamp == 0) {
            vault.lastAccrualTimestamp = block.timestamp;
            return;
        }

        uint256 timeElapsed = block.timestamp - vault.lastAccrualTimestamp;
        if (timeElapsed == 0) return;

        uint256 interest = VaultMath.calculateAccruedInterest(
            vault.debtAmount,
            collateralConfigs[collateral].stabilityFee,
            timeElapsed
        );

        if (interest > 0) {
            vault.debtAmount += interest;
            collateralConfigs[collateral].totalDebt += interest;
            totalGlobalDebt += interest;
            accruedFees += interest;
            vault.accruedInterest += interest;
            emit InterestAccrued(user, collateral, interest);
        }

        vault.lastAccrualTimestamp = block.timestamp;
    }

    function liquidate(
        address owner,
        address collateral,
        uint256 debtToCover
    ) external nonReentrant whenNotPaused onlyRole(LIQUIDATOR_ROLE) {
        require(debtToCover > 0, "VaultEngine: zero debt");

        Vault storage vault = vaults[owner][collateral];
        require(vault.debtAmount > 0, "VaultEngine: no debt");

        _accrueInterest(owner, collateral);

        uint256 collateralPrice = oracleAdapter.getPrice(collateral);
        uint256 collateralValue = (vault.collateralAmount * collateralPrice) / PRECISION;
        uint256 currentRatio = VaultMath.calculateCollateralRatio(collateralValue, vault.debtAmount);

        require(currentRatio < collateralConfigs[collateral].liquidationThreshold, "VaultEngine: not liquidatable");

        uint256 maxDebtToCover = (vault.debtAmount * 5000) / BASIS_POINTS;
        uint256 actualDebtToCover = VaultMath.min(debtToCover, maxDebtToCover);
        actualDebtToCover = VaultMath.min(actualDebtToCover, vault.debtAmount);

        uint256 collateralToSeize = VaultMath.calculateLiquidationAmount(
            actualDebtToCover,
            collateralPrice,
            collateralConfigs[collateral].liquidationPenalty
        );
        collateralToSeize = VaultMath.min(collateralToSeize, vault.collateralAmount);

        vault.collateralAmount -= collateralToSeize;
        vault.debtAmount -= actualDebtToCover;
        collateralConfigs[collateral].totalDebt -= actualDebtToCover;
        totalGlobalDebt -= actualDebtToCover;

        axusd.burn(msg.sender, actualDebtToCover);
        IERC20(collateral).safeTransfer(msg.sender, collateralToSeize);

        emit VaultLiquidated(owner, collateral, msg.sender, actualDebtToCover, collateralToSeize);
    }

    function getAccruedFees() external view returns (uint256) {
        return accruedFees;
    }

    function clearFeeAccounting() external onlyRole(ADMIN_ROLE) {
        require(accruedFees > 0, "VaultEngine: no fees");
        uint256 fees = accruedFees;
        accruedFees = 0;
        emit FeesRouted(feeBurner, fees);
    }

    function getVault(address user, address collateral) external view override returns (Vault memory) {
        return vaults[user][collateral];
    }

    function getCollateralRatio(address user, address collateral) external view override returns (uint256) {
        Vault memory vault = vaults[user][collateral];
        if (vault.collateralAmount == 0) return 0;
        if (vault.debtAmount == 0) return type(uint256).max;

        uint256 collateralPrice = oracleAdapter.getPrice(collateral);
        uint256 collateralValue = (vault.collateralAmount * collateralPrice) / PRECISION;
        return VaultMath.calculateCollateralRatio(collateralValue, vault.debtAmount);
    }

    function isLiquidatable(address user, address collateral) external view override returns (bool) {
        Vault memory vault = vaults[user][collateral];
        if (vault.debtAmount == 0) return false;

        uint256 collateralPrice = oracleAdapter.getPrice(collateral);
        uint256 collateralValue = (vault.collateralAmount * collateralPrice) / PRECISION;
        uint256 ratio = VaultMath.calculateCollateralRatio(collateralValue, vault.debtAmount);
        return ratio < collateralConfigs[collateral].liquidationThreshold;
    }

    function setGlobalDebtCeiling(uint256 newCeiling) external onlyRole(ADMIN_ROLE) {
        globalDebtCeiling = newCeiling;
        emit GlobalDebtCeilingUpdated(newCeiling);
    }

    function setOracleAdapter(address newAdapter) external onlyRole(ADMIN_ROLE) {
        require(newAdapter != address(0), "VaultEngine: zero address");
        oracleAdapter = IOracleAdapter(newAdapter);
        emit OracleAdapterUpdated(newAdapter);
    }

    function setRateLimiter(address newLimiter) external onlyRole(ADMIN_ROLE) {
        require(newLimiter != address(0), "VaultEngine: zero address");
        rateLimiter = IRateLimiter(newLimiter);
        emit RateLimiterUpdated(newLimiter);
    }

    function setFeeBurner(address newFeeBurner) external onlyRole(ADMIN_ROLE) {
        feeBurner = newFeeBurner;
        emit FeeBurnerUpdated(newFeeBurner);
    }

    function pause() external onlyRole(GUARDIAN_ROLE) {
        _pause();
    }

    function unpause() external onlyRole(ADMIN_ROLE) {
        _unpause();
    }

    function getCollateralConfig(address collateral) external view returns (CollateralConfig memory) {
        return collateralConfigs[collateral];
    }
}

