// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

interface ISEEDYieldDistributor {
    function depositRevenue(uint256 amount, string calldata source) external;
}

contract AXUSDRevenueRouter is AccessControl, ReentrancyGuard, Pausable {
    using SafeERC20 for IERC20;

    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");
    bytes32 public constant REVENUE_SOURCE_ROLE = keccak256("REVENUE_SOURCE_ROLE");

    IERC20 public axusd;
    address public seedYieldDistributor;
    address public treasuryVault;
    address public backstopVault;

    uint256 public constant BPS_DENOMINATOR = 10000;

    uint16 public seedShareBps = 5000;
    uint16 public treasuryShareBps = 3000;
    uint16 public backstopShareBps = 2000;

    uint256 public totalRevenueRouted;
    uint256 public totalToSEED;
    uint256 public totalToTreasury;
    uint256 public totalToBackstop;

    struct RevenueRecord {
        uint256 recordId;
        address source;
        uint256 amount;
        uint256 toSEED;
        uint256 toTreasury;
        uint256 toBackstop;
        string sourceType;
        uint256 timestamp;
    }

    uint256 public totalRecords;
    mapping(uint256 => RevenueRecord) public records;
    mapping(address => uint256) public sourceRevenue;

    event RevenueRouted(
        uint256 indexed recordId,
        address indexed source,
        uint256 amount,
        uint256 toSEED,
        uint256 toTreasury,
        uint256 toBackstop
    );
    event SharesUpdated(uint16 seedShare, uint16 treasuryShare, uint16 backstopShare);
    event DistributorUpdated(address indexed newDistributor);

    constructor(
        address _axusd,
        address _seedYieldDistributor,
        address _treasuryVault,
        address _backstopVault
    ) {
        require(_axusd != address(0), "Invalid AXUSD");
        require(_seedYieldDistributor != address(0), "Invalid SEED distributor");
        require(_treasuryVault != address(0), "Invalid treasury");
        require(_backstopVault != address(0), "Invalid backstop");

        axusd = IERC20(_axusd);
        seedYieldDistributor = _seedYieldDistributor;
        treasuryVault = _treasuryVault;
        backstopVault = _backstopVault;

        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(ADMIN_ROLE, msg.sender);
    }

    function routeRevenue(uint256 amount, string calldata sourceType) external onlyRole(REVENUE_SOURCE_ROLE) nonReentrant whenNotPaused {
        require(amount > 0, "Zero amount");

        axusd.safeTransferFrom(msg.sender, address(this), amount);

        uint256 toSEED = (amount * seedShareBps) / BPS_DENOMINATOR;
        uint256 toTreasury = (amount * treasuryShareBps) / BPS_DENOMINATOR;
        uint256 toBackstop = amount - toSEED - toTreasury;

        if (toSEED > 0) {
            axusd.approve(seedYieldDistributor, toSEED);
            ISEEDYieldDistributor(seedYieldDistributor).depositRevenue(toSEED, sourceType);
            totalToSEED += toSEED;
        }

        if (toTreasury > 0) {
            axusd.safeTransfer(treasuryVault, toTreasury);
            totalToTreasury += toTreasury;
        }

        if (toBackstop > 0) {
            axusd.safeTransfer(backstopVault, toBackstop);
            totalToBackstop += toBackstop;
        }

        totalRecords++;
        records[totalRecords] = RevenueRecord({
            recordId: totalRecords,
            source: msg.sender,
            amount: amount,
            toSEED: toSEED,
            toTreasury: toTreasury,
            toBackstop: toBackstop,
            sourceType: sourceType,
            timestamp: block.timestamp
        });

        sourceRevenue[msg.sender] += amount;
        totalRevenueRouted += amount;

        emit RevenueRouted(totalRecords, msg.sender, amount, toSEED, toTreasury, toBackstop);
    }

    function routePSMFees(uint256 amount) external onlyRole(REVENUE_SOURCE_ROLE) nonReentrant whenNotPaused {
        require(amount > 0, "Zero amount");
        axusd.safeTransferFrom(msg.sender, address(this), amount);

        uint256 toSEED = (amount * 8000) / BPS_DENOMINATOR;
        uint256 toBackstop = amount - toSEED;

        if (toSEED > 0) {
            axusd.approve(seedYieldDistributor, toSEED);
            ISEEDYieldDistributor(seedYieldDistributor).depositRevenue(toSEED, "PSM_FEES");
            totalToSEED += toSEED;
        }

        if (toBackstop > 0) {
            axusd.safeTransfer(backstopVault, toBackstop);
            totalToBackstop += toBackstop;
        }

        totalRevenueRouted += amount;
    }

    function routeKeyGrowRevenue(uint256 amount) external onlyRole(REVENUE_SOURCE_ROLE) nonReentrant whenNotPaused {
        require(amount > 0, "Zero amount");
        axusd.safeTransferFrom(msg.sender, address(this), amount);

        uint256 toSEED = (amount * 6000) / BPS_DENOMINATOR;
        uint256 toTreasury = (amount * 3000) / BPS_DENOMINATOR;
        uint256 toBackstop = amount - toSEED - toTreasury;

        if (toSEED > 0) {
            axusd.approve(seedYieldDistributor, toSEED);
            ISEEDYieldDistributor(seedYieldDistributor).depositRevenue(toSEED, "KEYGROW_REVENUE");
            totalToSEED += toSEED;
        }

        if (toTreasury > 0) {
            axusd.safeTransfer(treasuryVault, toTreasury);
            totalToTreasury += toTreasury;
        }

        if (toBackstop > 0) {
            axusd.safeTransfer(backstopVault, toBackstop);
            totalToBackstop += toBackstop;
        }

        totalRevenueRouted += amount;
    }

    function setShares(uint16 _seedShare, uint16 _treasuryShare, uint16 _backstopShare) external onlyRole(ADMIN_ROLE) {
        require(_seedShare + _treasuryShare + _backstopShare == BPS_DENOMINATOR, "Shares must equal 100%");
        seedShareBps = _seedShare;
        treasuryShareBps = _treasuryShare;
        backstopShareBps = _backstopShare;
        emit SharesUpdated(_seedShare, _treasuryShare, _backstopShare);
    }

    function setSEEDDistributor(address newDistributor) external onlyRole(ADMIN_ROLE) {
        require(newDistributor != address(0), "Invalid distributor");
        seedYieldDistributor = newDistributor;
        emit DistributorUpdated(newDistributor);
    }

    function getRevenueStats() external view returns (
        uint256 totalRouted,
        uint256 seedTotal,
        uint256 treasuryTotal,
        uint256 backstopTotal
    ) {
        return (totalRevenueRouted, totalToSEED, totalToTreasury, totalToBackstop);
    }

    function getRecord(uint256 recordId) external view returns (
        address source,
        uint256 amount,
        uint256 toSEED,
        uint256 toTreasury,
        uint256 toBackstop,
        string memory sourceType,
        uint256 timestamp
    ) {
        RevenueRecord storage record = records[recordId];
        return (
            record.source,
            record.amount,
            record.toSEED,
            record.toTreasury,
            record.toBackstop,
            record.sourceType,
            record.timestamp
        );
    }

    function pause() external onlyRole(ADMIN_ROLE) {
        _pause();
    }

    function unpause() external onlyRole(ADMIN_ROLE) {
        _unpause();
    }

    function emergencyWithdraw(uint256 amount) external onlyRole(ADMIN_ROLE) {
        axusd.safeTransfer(treasuryVault, amount);
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

interface IPSM {
    function swapUSDCToAXUSD(uint256 usdcAmount) external returns (uint256);
}

contract KeyGrowPaymentModule is AccessControl, ReentrancyGuard, Pausable {
    using SafeERC20 for IERC20;

    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");
    bytes32 public constant PROPERTY_MANAGER_ROLE = keccak256("PROPERTY_MANAGER_ROLE");
    bytes32 public constant OPERATOR_ROLE = keccak256("OPERATOR_ROLE");

    IERC20 public axusd;
    IERC20 public usdc;
    IPSM public psm;
    address public treasuryVault;

    uint256 public constant BPS_DENOMINATOR = 10000;
    uint16 public protocolFeeBps = 100;

    uint256 public totalProperties;
    uint256 public totalRentCollected;
    uint256 public totalEscrowDeposited;

    enum PropertyStatus { Available, Occupied, Completed, Cancelled }
    enum PaymentType { Rent, Escrow, DownPayment, BuyDown }

    struct Property {
        uint256 propertyId;
        address propertyManager;
        address tenant;
        uint256 monthlyRent;
        uint256 purchasePrice;
        uint256 escrowBalance;
        uint256 buyDownCredits;
        uint256 rentPaidCount;
        uint256 leaseStartTime;
        uint256 leaseDuration;
        PropertyStatus status;
        string propertyAddress;
    }

    struct PaymentRecord {
        uint256 propertyId;
        address payer;
        uint256 amount;
        PaymentType paymentType;
        uint256 timestamp;
    }

    mapping(uint256 => Property) public properties;
    mapping(uint256 => PaymentRecord[]) public propertyPayments;
    mapping(address => uint256[]) public tenantProperties;
    mapping(address => uint256) public tenantTotalPaid;

    event PropertyRegistered(uint256 indexed propertyId, address indexed manager, uint256 monthlyRent, uint256 purchasePrice);
    event TenantAssigned(uint256 indexed propertyId, address indexed tenant, uint256 leaseStart);
    event RentPaid(uint256 indexed propertyId, address indexed tenant, uint256 amount, uint256 buyDownCredit);
    event EscrowDeposited(uint256 indexed propertyId, address indexed tenant, uint256 amount);
    event DownPaymentMade(uint256 indexed propertyId, address indexed tenant, uint256 amount);
    event PropertyPurchased(uint256 indexed propertyId, address indexed buyer, uint256 totalPaid);
    event EscrowReleased(uint256 indexed propertyId, address indexed recipient, uint256 amount);

    constructor(
        address _axusd,
        address _usdc,
        address _psm,
        address _treasuryVault
    ) {
        require(_axusd != address(0), "Invalid AXUSD");
        require(_usdc != address(0), "Invalid USDC");
        require(_psm != address(0), "Invalid PSM");
        require(_treasuryVault != address(0), "Invalid treasury");

        axusd = IERC20(_axusd);
        usdc = IERC20(_usdc);
        psm = IPSM(_psm);
        treasuryVault = _treasuryVault;

        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(ADMIN_ROLE, msg.sender);
    }

    function registerProperty(
        uint256 monthlyRent,
        uint256 purchasePrice,
        uint256 leaseDuration,
        string calldata propertyAddress
    ) external onlyRole(PROPERTY_MANAGER_ROLE) returns (uint256) {
        require(monthlyRent >= 100 * 10**18, "Min rent 100 AXUSD");
        require(purchasePrice >= monthlyRent * 12, "Price must exceed annual rent");
        require(leaseDuration >= 12, "Min 12 month lease");

        totalProperties++;
        uint256 propertyId = totalProperties;

        properties[propertyId] = Property({
            propertyId: propertyId,
            propertyManager: msg.sender,
            tenant: address(0),
            monthlyRent: monthlyRent,
            purchasePrice: purchasePrice,
            escrowBalance: 0,
            buyDownCredits: 0,
            rentPaidCount: 0,
            leaseStartTime: 0,
            leaseDuration: leaseDuration,
            status: PropertyStatus.Available,
            propertyAddress: propertyAddress
        });

        emit PropertyRegistered(propertyId, msg.sender, monthlyRent, purchasePrice);
        return propertyId;
    }

    function assignTenant(uint256 propertyId, address tenant) external onlyRole(PROPERTY_MANAGER_ROLE) {
        Property storage prop = properties[propertyId];
        require(prop.propertyId > 0, "Property not found");
        require(prop.status == PropertyStatus.Available, "Not available");
        require(tenant != address(0), "Invalid tenant");

        prop.tenant = tenant;
        prop.leaseStartTime = block.timestamp;
        prop.status = PropertyStatus.Occupied;
        tenantProperties[tenant].push(propertyId);

        emit TenantAssigned(propertyId, tenant, block.timestamp);
    }

    function payRent(uint256 propertyId) external nonReentrant whenNotPaused {
        Property storage prop = properties[propertyId];
        require(prop.tenant == msg.sender, "Not tenant");
        require(prop.status == PropertyStatus.Occupied, "Not occupied");

        uint256 rentAmount = prop.monthlyRent;
        axusd.safeTransferFrom(msg.sender, address(this), rentAmount);

        uint256 fee = (rentAmount * protocolFeeBps) / BPS_DENOMINATOR;
        uint256 buyDownCredit = (rentAmount * 1000) / BPS_DENOMINATOR;
        uint256 managerPayment = rentAmount - fee - buyDownCredit;

        axusd.safeTransfer(treasuryVault, fee);
        axusd.safeTransfer(prop.propertyManager, managerPayment);

        prop.buyDownCredits += buyDownCredit;
        prop.rentPaidCount++;
        totalRentCollected += rentAmount;
        tenantTotalPaid[msg.sender] += rentAmount;

        propertyPayments[propertyId].push(PaymentRecord({
            propertyId: propertyId,
            payer: msg.sender,
            amount: rentAmount,
            paymentType: PaymentType.Rent,
            timestamp: block.timestamp
        }));

        emit RentPaid(propertyId, msg.sender, rentAmount, buyDownCredit);
    }

    function depositEscrow(uint256 propertyId, uint256 amount) external nonReentrant whenNotPaused {
        Property storage prop = properties[propertyId];
        require(prop.tenant == msg.sender, "Not tenant");
        require(prop.status == PropertyStatus.Occupied, "Not occupied");
        require(amount >= 100 * 10**18, "Min deposit 100 AXUSD");

        axusd.safeTransferFrom(msg.sender, address(this), amount);

        prop.escrowBalance += amount;
        totalEscrowDeposited += amount;
        tenantTotalPaid[msg.sender] += amount;

        propertyPayments[propertyId].push(PaymentRecord({
            propertyId: propertyId,
            payer: msg.sender,
            amount: amount,
            paymentType: PaymentType.Escrow,
            timestamp: block.timestamp
        }));

        emit EscrowDeposited(propertyId, msg.sender, amount);
    }

    function makeDownPayment(uint256 propertyId, uint256 amount) external nonReentrant whenNotPaused {
        Property storage prop = properties[propertyId];
        require(prop.tenant == msg.sender, "Not tenant");
        require(prop.status == PropertyStatus.Occupied, "Not occupied");

        axusd.safeTransferFrom(msg.sender, address(this), amount);

        prop.escrowBalance += amount;
        tenantTotalPaid[msg.sender] += amount;

        propertyPayments[propertyId].push(PaymentRecord({
            propertyId: propertyId,
            payer: msg.sender,
            amount: amount,
            paymentType: PaymentType.DownPayment,
            timestamp: block.timestamp
        }));

        emit DownPaymentMade(propertyId, msg.sender, amount);
    }

    function completePurchase(uint256 propertyId) external onlyRole(PROPERTY_MANAGER_ROLE) nonReentrant {
        Property storage prop = properties[propertyId];
        require(prop.status == PropertyStatus.Occupied, "Not occupied");

        uint256 totalEquity = prop.escrowBalance + prop.buyDownCredits;
        require(totalEquity >= prop.purchasePrice, "Insufficient equity");

        axusd.safeTransfer(prop.propertyManager, prop.escrowBalance);

        prop.status = PropertyStatus.Completed;
        prop.escrowBalance = 0;

        emit PropertyPurchased(propertyId, prop.tenant, totalEquity);
    }

    function releaseEscrow(uint256 propertyId, address recipient, uint256 amount) external onlyRole(PROPERTY_MANAGER_ROLE) nonReentrant {
        Property storage prop = properties[propertyId];
        require(prop.escrowBalance >= amount, "Insufficient escrow");

        prop.escrowBalance -= amount;
        axusd.safeTransfer(recipient, amount);

        emit EscrowReleased(propertyId, recipient, amount);
    }

    function getPropertyInfo(uint256 propertyId) external view returns (
        address propertyManager,
        address tenant,
        uint256 monthlyRent,
        uint256 purchasePrice,
        uint256 escrowBalance,
        uint256 buyDownCredits,
        uint256 rentPaidCount,
        PropertyStatus status
    ) {
        Property storage prop = properties[propertyId];
        return (
            prop.propertyManager,
            prop.tenant,
            prop.monthlyRent,
            prop.purchasePrice,
            prop.escrowBalance,
            prop.buyDownCredits,
            prop.rentPaidCount,
            prop.status
        );
    }

    function getTenantEquity(uint256 propertyId) external view returns (uint256 escrow, uint256 buyDown, uint256 total) {
        Property storage prop = properties[propertyId];
        return (prop.escrowBalance, prop.buyDownCredits, prop.escrowBalance + prop.buyDownCredits);
    }

    function getPaymentHistory(uint256 propertyId) external view returns (PaymentRecord[] memory) {
        return propertyPayments[propertyId];
    }

    function setProtocolFee(uint16 newFeeBps) external onlyRole(ADMIN_ROLE) {
        require(newFeeBps <= 500, "Fee too high");
        protocolFeeBps = newFeeBps;
    }

    function pause() external onlyRole(ADMIN_ROLE) {
        _pause();
    }

    function unpause() external onlyRole(ADMIN_ROLE) {
        _unpause();
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

interface IUniswapV2Router {
    function addLiquidity(
        address tokenA,
        address tokenB,
        uint256 amountADesired,
        uint256 amountBDesired,
        uint256 amountAMin,
        uint256 amountBMin,
        address to,
        uint256 deadline
    ) external returns (uint256 amountA, uint256 amountB, uint256 liquidity);

    function removeLiquidity(
        address tokenA,
        address tokenB,
        uint256 liquidity,
        uint256 amountAMin,
        uint256 amountBMin,
        address to,
        uint256 deadline
    ) external returns (uint256 amountA, uint256 amountB);
}

interface IUniswapV2Factory {
    function getPair(address tokenA, address tokenB) external view returns (address);
}

contract LiquidityBootstrapper is AccessControl, ReentrancyGuard, Pausable {
    using SafeERC20 for IERC20;

    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");
    bytes32 public constant LIQUIDITY_MANAGER_ROLE = keccak256("LIQUIDITY_MANAGER_ROLE");

    IERC20 public axusd;
    address public treasuryVault;
    IUniswapV2Router public router;
    IUniswapV2Factory public factory;

    uint256 public constant MIN_SEED_AMOUNT = 1000 * 10**18;
    uint256 public totalLiquiditySeeded;
    uint256 public totalPoolsCreated;

    enum PoolStatus { Pending, Active, Closed }

    struct LiquidityPool {
        uint256 poolId;
        address tokenA;
        address tokenB;
        address lpToken;
        uint256 axusdSeeded;
        uint256 pairedTokenSeeded;
        uint256 lpTokensReceived;
        uint256 createdAt;
        PoolStatus status;
        string name;
    }

    struct PoolStats {
        uint256 currentAXUSDBalance;
        uint256 currentPairedBalance;
        uint256 protocolLPBalance;
    }

    mapping(uint256 => LiquidityPool) public pools;
    mapping(address => mapping(address => uint256)) public pairToPoolId;

    event PoolSeeded(
        uint256 indexed poolId,
        address indexed tokenA,
        address indexed tokenB,
        uint256 amountA,
        uint256 amountB,
        uint256 lpTokens
    );
    event LiquidityAdded(uint256 indexed poolId, uint256 axusdAmount, uint256 pairedAmount, uint256 lpTokens);
    event LiquidityRemoved(uint256 indexed poolId, uint256 lpTokens, uint256 axusdReceived, uint256 pairedReceived);
    event PoolClosed(uint256 indexed poolId);

    constructor(
        address _axusd,
        address _router,
        address _factory,
        address _treasuryVault
    ) {
        require(_axusd != address(0), "Invalid AXUSD");
        require(_router != address(0), "Invalid router");
        require(_factory != address(0), "Invalid factory");
        require(_treasuryVault != address(0), "Invalid treasury");

        axusd = IERC20(_axusd);
        router = IUniswapV2Router(_router);
        factory = IUniswapV2Factory(_factory);
        treasuryVault = _treasuryVault;

        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(ADMIN_ROLE, msg.sender);
    }

    function seedPool(
        address pairedToken,
        uint256 axusdAmount,
        uint256 pairedAmount,
        string calldata poolName
    ) external onlyRole(LIQUIDITY_MANAGER_ROLE) nonReentrant returns (uint256) {
        require(pairedToken != address(0), "Invalid paired token");
        require(axusdAmount >= MIN_SEED_AMOUNT, "Below minimum seed");
        require(pairedAmount > 0, "Zero paired amount");

        axusd.safeTransferFrom(msg.sender, address(this), axusdAmount);
        IERC20(pairedToken).safeTransferFrom(msg.sender, address(this), pairedAmount);

        axusd.approve(address(router), axusdAmount);
        IERC20(pairedToken).approve(address(router), pairedAmount);

        (uint256 amountA, uint256 amountB, uint256 liquidity) = router.addLiquidity(
            address(axusd),
            pairedToken,
            axusdAmount,
            pairedAmount,
            (axusdAmount * 95) / 100,
            (pairedAmount * 95) / 100,
            address(this),
            block.timestamp + 300
        );

        totalPoolsCreated++;
        uint256 poolId = totalPoolsCreated;

        address lpToken = factory.getPair(address(axusd), pairedToken);

        pools[poolId] = LiquidityPool({
            poolId: poolId,
            tokenA: address(axusd),
            tokenB: pairedToken,
            lpToken: lpToken,
            axusdSeeded: amountA,
            pairedTokenSeeded: amountB,
            lpTokensReceived: liquidity,
            createdAt: block.timestamp,
            status: PoolStatus.Active,
            name: poolName
        });

        pairToPoolId[address(axusd)][pairedToken] = poolId;
        totalLiquiditySeeded += amountA;

        emit PoolSeeded(poolId, address(axusd), pairedToken, amountA, amountB, liquidity);
        return poolId;
    }

    function addLiquidity(
        uint256 poolId,
        uint256 axusdAmount,
        uint256 pairedAmount
    ) external onlyRole(LIQUIDITY_MANAGER_ROLE) nonReentrant {
        LiquidityPool storage pool = pools[poolId];
        require(pool.status == PoolStatus.Active, "Pool not active");

        axusd.safeTransferFrom(msg.sender, address(this), axusdAmount);
        IERC20(pool.tokenB).safeTransferFrom(msg.sender, address(this), pairedAmount);

        axusd.approve(address(router), axusdAmount);
        IERC20(pool.tokenB).approve(address(router), pairedAmount);

        (uint256 amountA, uint256 amountB, uint256 liquidity) = router.addLiquidity(
            address(axusd),
            pool.tokenB,
            axusdAmount,
            pairedAmount,
            (axusdAmount * 95) / 100,
            (pairedAmount * 95) / 100,
            address(this),
            block.timestamp + 300
        );

        pool.axusdSeeded += amountA;
        pool.pairedTokenSeeded += amountB;
        pool.lpTokensReceived += liquidity;
        totalLiquiditySeeded += amountA;

        emit LiquidityAdded(poolId, amountA, amountB, liquidity);
    }

    function removeLiquidity(
        uint256 poolId,
        uint256 lpTokenAmount
    ) external onlyRole(ADMIN_ROLE) nonReentrant {
        LiquidityPool storage pool = pools[poolId];
        require(pool.lpTokensReceived >= lpTokenAmount, "Insufficient LP tokens");

        IERC20(pool.lpToken).approve(address(router), lpTokenAmount);

        (uint256 amountA, uint256 amountB) = router.removeLiquidity(
            address(axusd),
            pool.tokenB,
            lpTokenAmount,
            0,
            0,
            treasuryVault,
            block.timestamp + 300
        );

        pool.lpTokensReceived -= lpTokenAmount;

        emit LiquidityRemoved(poolId, lpTokenAmount, amountA, amountB);
    }

    function closePool(uint256 poolId) external onlyRole(ADMIN_ROLE) nonReentrant {
        LiquidityPool storage pool = pools[poolId];
        require(pool.status == PoolStatus.Active, "Pool not active");

        if (pool.lpTokensReceived > 0) {
            IERC20(pool.lpToken).approve(address(router), pool.lpTokensReceived);
            router.removeLiquidity(
                address(axusd),
                pool.tokenB,
                pool.lpTokensReceived,
                0,
                0,
                treasuryVault,
                block.timestamp + 300
            );
            pool.lpTokensReceived = 0;
        }

        pool.status = PoolStatus.Closed;
        emit PoolClosed(poolId);
    }

    function getPoolInfo(uint256 poolId) external view returns (
        address tokenA,
        address tokenB,
        address lpToken,
        uint256 axusdSeeded,
        uint256 pairedSeeded,
        uint256 lpTokens,
        PoolStatus status,
        string memory name
    ) {
        LiquidityPool storage pool = pools[poolId];
        return (
            pool.tokenA,
            pool.tokenB,
            pool.lpToken,
            pool.axusdSeeded,
            pool.pairedTokenSeeded,
            pool.lpTokensReceived,
            pool.status,
            pool.name
        );
    }

    function getProtocolLPBalance(uint256 poolId) external view returns (uint256) {
        return pools[poolId].lpTokensReceived;
    }

    function pause() external onlyRole(ADMIN_ROLE) {
        _pause();
    }

    function unpause() external onlyRole(ADMIN_ROLE) {
        _unpause();
    }

    function emergencyWithdraw(address token, uint256 amount) external onlyRole(ADMIN_ROLE) {
        IERC20(token).safeTransfer(treasuryVault, amount);
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

interface ISEED {
    function balanceOf(address account) external view returns (uint256);
    function totalSupply() external view returns (uint256);
    function lockEnd(address account) external view returns (uint256);
}

contract SEEDYieldDistributor is AccessControl, ReentrancyGuard, Pausable {
    using SafeERC20 for IERC20;

    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");
    bytes32 public constant REVENUE_ROUTER_ROLE = keccak256("REVENUE_ROUTER_ROLE");

    IERC20 public axusd;
    ISEED public seed;
    address public treasuryVault;

    uint256 public constant EPOCH_DURATION = 7 days;
    uint256 public constant MIN_CLAIM_AMOUNT = 1 * 10**18;

    uint256 public currentEpoch;
    uint256 public epochStartTime;
    uint256 public totalDistributed;
    uint256 public totalClaimed;

    struct Epoch {
        uint256 epochId;
        uint256 totalRevenue;
        uint256 totalSEEDSupply;
        uint256 revenuePerSEED;
        uint256 startTime;
        uint256 endTime;
        bool finalized;
    }

    struct UserClaim {
        uint256 lastClaimedEpoch;
        uint256 totalClaimed;
        uint256 pendingRewards;
    }

    mapping(uint256 => Epoch) public epochs;
    mapping(address => UserClaim) public userClaims;
    mapping(uint256 => mapping(address => bool)) public epochClaimed;
    mapping(uint256 => uint256) public epochUserSEEDBalance;

    event RevenueDeposited(uint256 indexed epochId, uint256 amount, string source);
    event EpochFinalized(uint256 indexed epochId, uint256 totalRevenue, uint256 revenuePerSEED);
    event YieldClaimed(address indexed user, uint256 indexed epochId, uint256 amount);
    event NewEpochStarted(uint256 indexed epochId, uint256 startTime);

    constructor(
        address _axusd,
        address _seed,
        address _treasuryVault
    ) {
        require(_axusd != address(0), "Invalid AXUSD");
        require(_seed != address(0), "Invalid SEED");
        require(_treasuryVault != address(0), "Invalid treasury");

        axusd = IERC20(_axusd);
        seed = ISEED(_seed);
        treasuryVault = _treasuryVault;

        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(ADMIN_ROLE, msg.sender);

        currentEpoch = 1;
        epochStartTime = block.timestamp;

        epochs[currentEpoch] = Epoch({
            epochId: currentEpoch,
            totalRevenue: 0,
            totalSEEDSupply: 0,
            revenuePerSEED: 0,
            startTime: block.timestamp,
            endTime: block.timestamp + EPOCH_DURATION,
            finalized: false
        });

        emit NewEpochStarted(currentEpoch, block.timestamp);
    }

    function depositRevenue(uint256 amount, string calldata source) external onlyRole(REVENUE_ROUTER_ROLE) nonReentrant {
        require(amount > 0, "Zero amount");

        axusd.safeTransferFrom(msg.sender, address(this), amount);

        Epoch storage epoch = epochs[currentEpoch];
        epoch.totalRevenue += amount;
        totalDistributed += amount;

        emit RevenueDeposited(currentEpoch, amount, source);
    }

    function finalizeEpoch() external onlyRole(ADMIN_ROLE) {
        Epoch storage epoch = epochs[currentEpoch];
        require(!epoch.finalized, "Already finalized");
        require(block.timestamp >= epoch.endTime, "Epoch not ended");

        uint256 totalSEED = seed.totalSupply();
        epoch.totalSEEDSupply = totalSEED;

        if (totalSEED > 0 && epoch.totalRevenue > 0) {
            epoch.revenuePerSEED = (epoch.totalRevenue * 10**18) / totalSEED;
        }

        epoch.finalized = true;

        emit EpochFinalized(currentEpoch, epoch.totalRevenue, epoch.revenuePerSEED);

        currentEpoch++;
        epochs[currentEpoch] = Epoch({
            epochId: currentEpoch,
            totalRevenue: 0,
            totalSEEDSupply: 0,
            revenuePerSEED: 0,
            startTime: block.timestamp,
            endTime: block.timestamp + EPOCH_DURATION,
            finalized: false
        });

        emit NewEpochStarted(currentEpoch, block.timestamp);
    }

    function claim(uint256 epochId) external nonReentrant whenNotPaused {
        require(epochId > 0 && epochId < currentEpoch, "Invalid epoch");
        require(!epochClaimed[epochId][msg.sender], "Already claimed");

        Epoch storage epoch = epochs[epochId];
        require(epoch.finalized, "Epoch not finalized");

        uint256 userSEED = seed.balanceOf(msg.sender);
        require(userSEED > 0, "No SEED balance");

        uint256 userLockEnd = seed.lockEnd(msg.sender);
        require(userLockEnd > epoch.startTime, "Lock expired before epoch");

        uint256 reward = (userSEED * epoch.revenuePerSEED) / 10**18;
        require(reward >= MIN_CLAIM_AMOUNT, "Reward below minimum");

        epochClaimed[epochId][msg.sender] = true;

        UserClaim storage userClaim = userClaims[msg.sender];
        userClaim.lastClaimedEpoch = epochId;
        userClaim.totalClaimed += reward;
        totalClaimed += reward;

        axusd.safeTransfer(msg.sender, reward);

        emit YieldClaimed(msg.sender, epochId, reward);
    }

    function claimMultipleEpochs(uint256[] calldata epochIds) external nonReentrant whenNotPaused {
        uint256 totalReward = 0;
        uint256 userSEED = seed.balanceOf(msg.sender);
        require(userSEED > 0, "No SEED balance");

        for (uint256 i = 0; i < epochIds.length; i++) {
            uint256 epochId = epochIds[i];
            if (epochId == 0 || epochId >= currentEpoch) continue;
            if (epochClaimed[epochId][msg.sender]) continue;

            Epoch storage epoch = epochs[epochId];
            if (!epoch.finalized) continue;

            uint256 userLockEnd = seed.lockEnd(msg.sender);
            if (userLockEnd <= epoch.startTime) continue;

            uint256 reward = (userSEED * epoch.revenuePerSEED) / 10**18;
            if (reward < MIN_CLAIM_AMOUNT) continue;

            epochClaimed[epochId][msg.sender] = true;
            totalReward += reward;

            emit YieldClaimed(msg.sender, epochId, reward);
        }

        require(totalReward > 0, "No rewards to claim");

        UserClaim storage userClaim = userClaims[msg.sender];
        userClaim.totalClaimed += totalReward;
        totalClaimed += totalReward;

        axusd.safeTransfer(msg.sender, totalReward);
    }

    function getPendingRewards(address user) external view returns (uint256 totalPending, uint256[] memory epochIds, uint256[] memory amounts) {
        uint256 userSEED = seed.balanceOf(user);
        if (userSEED == 0) return (0, new uint256[](0), new uint256[](0));

        uint256 count = 0;
        for (uint256 i = 1; i < currentEpoch; i++) {
            if (!epochClaimed[i][user] && epochs[i].finalized) {
                count++;
            }
        }

        epochIds = new uint256[](count);
        amounts = new uint256[](count);
        uint256 index = 0;

        for (uint256 i = 1; i < currentEpoch; i++) {
            if (!epochClaimed[i][user] && epochs[i].finalized) {
                Epoch storage epoch = epochs[i];
                uint256 reward = (userSEED * epoch.revenuePerSEED) / 10**18;
                if (reward >= MIN_CLAIM_AMOUNT) {
                    epochIds[index] = i;
                    amounts[index] = reward;
                    totalPending += reward;
                    index++;
                }
            }
        }
    }

    function getEpochInfo(uint256 epochId) external view returns (
        uint256 totalRevenue,
        uint256 totalSEEDSupply,
        uint256 revenuePerSEED,
        bool finalized,
        uint256 startTime,
        uint256 endTime
    ) {
        Epoch storage epoch = epochs[epochId];
        return (
            epoch.totalRevenue,
            epoch.totalSEEDSupply,
            epoch.revenuePerSEED,
            epoch.finalized,
            epoch.startTime,
            epoch.endTime
        );
    }

    function getUserClaimInfo(address user) external view returns (
        uint256 lastClaimedEpoch,
        uint256 totalClaimedAmount,
        uint256 seedBalance
    ) {
        UserClaim storage claim = userClaims[user];
        return (claim.lastClaimedEpoch, claim.totalClaimed, seed.balanceOf(user));
    }

    function pause() external onlyRole(ADMIN_ROLE) {
        _pause();
    }

    function unpause() external onlyRole(ADMIN_ROLE) {
        _unpause();
    }

    function emergencyWithdraw(uint256 amount) external onlyRole(ADMIN_ROLE) {
        axusd.safeTransfer(treasuryVault, amount);
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

interface IPSM {
    function swapUSDCToAXUSD(uint256 usdcAmount) external returns (uint256);
    function swapAXUSDToUSDC(uint256 axusdAmount) external returns (uint256);
    function getQuoteUSDCToAXUSD(uint256 usdcAmount) external view returns (uint256);
}

interface ISusuPersonalVault {
    function createCircle(
        address token,
        uint256 targetMembers,
        uint256 contributionPerCycle,
        uint256 cycleDuration
    ) external returns (uint256);
}

contract SusuAXUSDAdapter is AccessControl, ReentrancyGuard, Pausable {
    using SafeERC20 for IERC20;

    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");
    bytes32 public constant OPERATOR_ROLE = keccak256("OPERATOR_ROLE");

    IERC20 public axusd;
    IERC20 public usdc;
    IPSM public psm;
    address public susuVault;
    address public treasuryVault;

    uint256 public constant BPS_DENOMINATOR = 10000;
    uint16 public protocolFeeBps = 50;

    uint256 public totalCirclesCreated;
    uint256 public totalAXUSDDeposited;
    uint256 public totalUSDCConverted;

    struct AXUSDCircle {
        uint256 circleId;
        uint256 susuCircleId;
        address organizer;
        uint256 targetMembers;
        uint256 contributionPerCycle;
        uint256 cycleDuration;
        uint256 totalDeposited;
        bool active;
        uint256 createdAt;
    }

    mapping(uint256 => AXUSDCircle) public circles;
    mapping(uint256 => mapping(address => uint256)) public memberDeposits;
    mapping(uint256 => address[]) public circleMembers;
    mapping(address => uint256) public userTotalDeposits;

    event CircleCreated(
        uint256 indexed circleId,
        address indexed organizer,
        uint256 targetMembers,
        uint256 contributionPerCycle
    );
    event DepositedAXUSD(uint256 indexed circleId, address indexed member, uint256 amount);
    event DepositedUSDC(uint256 indexed circleId, address indexed member, uint256 usdcAmount, uint256 axusdReceived);
    event PayoutProcessed(uint256 indexed circleId, address indexed recipient, uint256 amount);
    event CircleCompleted(uint256 indexed circleId);

    constructor(
        address _axusd,
        address _usdc,
        address _psm,
        address _susuVault,
        address _treasuryVault
    ) {
        require(_axusd != address(0), "Invalid AXUSD");
        require(_usdc != address(0), "Invalid USDC");
        require(_psm != address(0), "Invalid PSM");
        require(_susuVault != address(0), "Invalid SUSU vault");
        require(_treasuryVault != address(0), "Invalid treasury");

        axusd = IERC20(_axusd);
        usdc = IERC20(_usdc);
        psm = IPSM(_psm);
        susuVault = _susuVault;
        treasuryVault = _treasuryVault;

        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(ADMIN_ROLE, msg.sender);
    }

    function createAXUSDCircle(
        uint256 targetMembers,
        uint256 contributionPerCycle,
        uint256 cycleDuration
    ) external whenNotPaused returns (uint256) {
        require(targetMembers >= 2 && targetMembers <= 20, "Invalid member count");
        require(contributionPerCycle >= 10 * 10**18, "Min contribution 10 AXUSD");
        require(cycleDuration >= 1 days && cycleDuration <= 90 days, "Invalid cycle duration");

        totalCirclesCreated++;
        uint256 circleId = totalCirclesCreated;

        circles[circleId] = AXUSDCircle({
            circleId: circleId,
            susuCircleId: 0,
            organizer: msg.sender,
            targetMembers: targetMembers,
            contributionPerCycle: contributionPerCycle,
            cycleDuration: cycleDuration,
            totalDeposited: 0,
            active: true,
            createdAt: block.timestamp
        });

        circleMembers[circleId].push(msg.sender);

        emit CircleCreated(circleId, msg.sender, targetMembers, contributionPerCycle);
        return circleId;
    }

    function depositAXUSD(uint256 circleId, uint256 amount) external nonReentrant whenNotPaused {
        AXUSDCircle storage circle = circles[circleId];
        require(circle.active, "Circle not active");
        require(amount >= circle.contributionPerCycle, "Below minimum");

        axusd.safeTransferFrom(msg.sender, address(this), amount);

        if (memberDeposits[circleId][msg.sender] == 0) {
            circleMembers[circleId].push(msg.sender);
        }

        memberDeposits[circleId][msg.sender] += amount;
        circle.totalDeposited += amount;
        userTotalDeposits[msg.sender] += amount;
        totalAXUSDDeposited += amount;

        emit DepositedAXUSD(circleId, msg.sender, amount);
    }

    function depositUSDC(uint256 circleId, uint256 usdcAmount) external nonReentrant whenNotPaused {
        AXUSDCircle storage circle = circles[circleId];
        require(circle.active, "Circle not active");

        usdc.safeTransferFrom(msg.sender, address(this), usdcAmount);
        usdc.approve(address(psm), usdcAmount);

        uint256 axusdReceived = psm.swapUSDCToAXUSD(usdcAmount);
        require(axusdReceived >= circle.contributionPerCycle, "Converted amount below minimum");

        if (memberDeposits[circleId][msg.sender] == 0) {
            circleMembers[circleId].push(msg.sender);
        }

        memberDeposits[circleId][msg.sender] += axusdReceived;
        circle.totalDeposited += axusdReceived;
        userTotalDeposits[msg.sender] += axusdReceived;
        totalAXUSDDeposited += axusdReceived;
        totalUSDCConverted += usdcAmount;

        emit DepositedUSDC(circleId, msg.sender, usdcAmount, axusdReceived);
    }

    function getQuoteUSDCToAXUSD(uint256 usdcAmount) external view returns (uint256) {
        return psm.getQuoteUSDCToAXUSD(usdcAmount);
    }

    function processPayout(uint256 circleId, address recipient) external onlyRole(OPERATOR_ROLE) nonReentrant {
        AXUSDCircle storage circle = circles[circleId];
        require(circle.active, "Circle not active");
        require(memberDeposits[circleId][recipient] > 0, "Not a member");

        uint256 payoutAmount = circle.contributionPerCycle * circle.targetMembers;
        uint256 fee = (payoutAmount * protocolFeeBps) / BPS_DENOMINATOR;
        uint256 netPayout = payoutAmount - fee;

        require(axusd.balanceOf(address(this)) >= payoutAmount, "Insufficient balance");

        if (fee > 0) {
            axusd.safeTransfer(treasuryVault, fee);
        }
        axusd.safeTransfer(recipient, netPayout);

        emit PayoutProcessed(circleId, recipient, netPayout);
    }

    function completeCircle(uint256 circleId) external onlyRole(OPERATOR_ROLE) {
        AXUSDCircle storage circle = circles[circleId];
        require(circle.active, "Already inactive");
        circle.active = false;
        emit CircleCompleted(circleId);
    }

    function getCircleInfo(uint256 circleId) external view returns (
        address organizer,
        uint256 targetMembers,
        uint256 contributionPerCycle,
        uint256 totalDeposited,
        uint256 memberCount,
        bool active
    ) {
        AXUSDCircle storage circle = circles[circleId];
        return (
            circle.organizer,
            circle.targetMembers,
            circle.contributionPerCycle,
            circle.totalDeposited,
            circleMembers[circleId].length,
            circle.active
        );
    }

    function getMemberDeposit(uint256 circleId, address member) external view returns (uint256) {
        return memberDeposits[circleId][member];
    }

    function setProtocolFee(uint16 newFeeBps) external onlyRole(ADMIN_ROLE) {
        require(newFeeBps <= 500, "Fee too high");
        protocolFeeBps = newFeeBps;
    }

    function pause() external onlyRole(ADMIN_ROLE) {
        _pause();
    }

    function unpause() external onlyRole(ADMIN_ROLE) {
        _unpause();
    }

    function emergencyWithdraw(address token, uint256 amount) external onlyRole(ADMIN_ROLE) {
        IERC20(token).safeTransfer(treasuryVault, amount);
    }
}

